// ---------- Hilfsfunktionen ----------

const DREI_TAGE_MS = 3 * 24 * 60 * 60 * 1000;
const EINEN_TAG_MS = 24 * 60 * 60 * 1000;

// Turniere verschwinden aus der Vereins-Ansicht einen Tag nach dem Turniertermin
// (bleiben im Admin-Bereich aber weiterhin sichtbar, z. B. für CSV-Export/Archiv).
function turnierFuerTeilnehmerSichtbar(turnier, jetzt) {
  const sichtbarBis = new Date(turnier.datum).getTime() + 2 * EINEN_TAG_MS;
  return jetzt < sichtbarBis;
}

function neueId(prefix) {
  return prefix + "_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

// Sorgt dafür, dass Zahlungslinks auch dann funktionieren, wenn beim Anlegen des Turniers
// aus Versehen "https://" vergessen wurde (sonst versucht der Browser, den Link relativ zur
// eigenen Seite zu interpretieren, statt zu z. B. PayPal weiterzuleiten).
function normalisiereLink(url) {
  if (!url) return url;
  const bereinigt = url.trim();
  if (/^https?:\/\//i.test(bereinigt)) return bereinigt;
  return "https://" + bereinigt;
}

function formatDatum(iso) {
  if (!iso) return "–";
  try {
    return new Intl.DateTimeFormat("de-DE", { day: "2-digit", month: "long", year: "numeric" }).format(new Date(iso));
  } catch {
    return iso;
  }
}

function formatDatumZeit(ts) {
  if (!ts) return "–";
  return new Intl.DateTimeFormat("de-DE", {
    day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit"
  }).format(new Date(ts));
}

function restzeit(ms) {
  if (ms <= 0) return "abgelaufen";
  const tage = Math.floor(ms / (24 * 60 * 60 * 1000));
  const stunden = Math.floor((ms % (24 * 60 * 60 * 1000)) / (60 * 60 * 1000));
  const minuten = Math.floor((ms % (60 * 60 * 1000)) / (60 * 1000));
  if (tage > 0) return `${tage} Tag${tage !== 1 ? "e" : ""} ${stunden} Std.`;
  if (stunden > 0) return `${stunden} Std. ${minuten} Min.`;
  return `${minuten} Min.`;
}

// Status, wie er tatsächlich gilt (Ablauf wird "on the fly" berechnet, nicht persistiert)
function effektiverStatus(reg, jetzt) {
  if ((reg.status === "ausstehend" || reg.status === "zahlung_gemeldet") && jetzt > reg.frist) {
    return "abgelaufen";
  }
  return reg.status;
}

const STATUS_LABEL = {
  ausstehend: "Zahlung ausstehend",
  zahlung_gemeldet: "Zahlung gemeldet – wird geprüft",
  bestaetigt: "Teilnahme bestätigt",
  abgelehnt: "Zahlung abgelehnt",
  abgelaufen: "Frist abgelaufen – nicht bestätigt",
  warteliste: "Auf Warteliste",
};

