// ---------- E-Mail-Benachrichtigungen ----------
//
// Ohne eigenen Server kann eine Web-App keine E-Mails im Hintergrund verschicken (ein API-Schlüssel
// eines Mail-Anbieters dürfte niemals im Browser-Code stehen). Diese Funktionen öffnen daher den
// E-Mail-Client des Admins mit fertig ausgefüllter Nachricht – der Admin muss nur noch "Senden" klicken.
// Für vollautomatischen Versand ohne diesen letzten Klick siehe die separate Backend-Vorlage.

// Wird gesetzt, sobald ein eigenes Backend (siehe kidzcup-email-backend/) deployt wurde.
// Solange die URL leer ist, passiert hier nichts – die App funktioniert unverändert mit den mailto-Buttons.
const E_MAIL_WEBHOOK_URL = "";
const E_MAIL_WEBHOOK_SECRET = ""; // muss mit WEBHOOK_SECRET im Backend übereinstimmen, falls dort gesetzt

function mailtoLink(empfaenger, betreff, text) {
  return `mailto:${empfaenger}?subject=${encodeURIComponent(betreff)}&body=${encodeURIComponent(text)}`;
}

function mailVorlage(typ, anmeldung, turnier) {
  const frist = anmeldung.frist ? formatDatumZeit(anmeldung.frist) : "";
  const termin = turnier ? `${formatDatum(turnier.datum)} in ${turnier.ort}` : "";
  const gruss = `Sportliche Grüße\nDein KIDZCUP-Team`;

  if (typ === "erinnerung") {
    return {
      betreff: `Erinnerung: Zahlung für ${turnier?.name || "euer Turnier"} noch offen`,
      text:
        `Hallo ${anmeldung.trainer || ""},\n\n` +
        `eure Anmeldung von ${anmeldung.verein} für "${turnier?.name}" (${termin}) ist noch nicht bestätigt, ` +
        `da die Startgebühr von ${turnier?.preis} € bisher nicht bei uns eingegangen ist.\n\n` +
        `Bitte zahlt bis spätestens ${frist} über folgenden Link:\n${turnier?.zahlLink || "(Zahlungslink beim Veranstalter erfragen)"}\n\n` +
        `Ohne fristgerechte Zahlung können wir die Teilnahme leider nicht bestätigen.\n\n${gruss}`,
    };
  }
  if (typ === "bestaetigung") {
    return {
      betreff: `Teilnahme bestätigt – ${turnier?.name || "KIDZCUP"}`,
      text:
        `Hallo ${anmeldung.trainer || ""},\n\n` +
        `eure Zahlung ist bei uns eingegangen – die Teilnahme von ${anmeldung.verein} (Jahrgang ${anmeldung.jahrgang}, ${anmeldung.jugend}) ` +
        `am Turnier "${turnier?.name}" am ${termin} steht damit fest.\n\n` +
        `Wir freuen uns auf euch!\n\n${gruss}`,
    };
  }
  if (typ === "ablehnung") {
    return {
      betreff: `Zahlung nicht bestätigt – ${turnier?.name || "KIDZCUP"}`,
      text:
        `Hallo ${anmeldung.trainer || ""},\n\n` +
        `leider konnten wir die gemeldete Zahlung für "${turnier?.name}" (${anmeldung.verein}) nicht zuordnen bzw. bestätigen.\n\n` +
        `Bitte meldet euch kurz bei uns, damit wir das gemeinsam klären können.\n\n${gruss}`,
    };
  }
  if (typ === "warteliste_aufnahme") {
    return {
      betreff: `Platz frei geworden – ${turnier?.name || "KIDZCUP"}`,
      text:
        `Hallo ${anmeldung.trainer || ""},\n\n` +
        `gute Neuigkeiten: Für "${turnier?.name}" (${termin}) ist ein Platz frei geworden und eure Mannschaft ${anmeldung.verein} ` +
        `rückt von der Warteliste ins Turnier nach.\n\n` +
        `Bitte zahlt die Startgebühr von ${turnier?.preis} € bis spätestens ${frist} über:\n${turnier?.zahlLink || "(Zahlungslink beim Veranstalter erfragen)"}\n\n` +
        `Ohne fristgerechte Zahlung wird der Platz erneut freigegeben.\n\n${gruss}`,
    };
  }
  return { betreff: "", text: "" };
}

function mailOeffnen(typ, anmeldung, turnier) {
  const { betreff, text } = mailVorlage(typ, anmeldung, turnier);
  if (!anmeldung.email) return;
  window.open(mailtoLink(anmeldung.email, betreff, text), "_blank");
}

// Optionaler Aufruf eines selbst gehosteten Backends für vollautomatischen Versand.
// Schlägt der Aufruf fehl (z. B. weil keine URL gesetzt ist oder kein Netzwerkzugriff besteht),
// wird das bewusst nur geloggt – die App bleibt auch ohne Backend voll funktionsfähig.
async function benachrichtigeBackend(ereignis, anmeldung, turnier) {
  if (!E_MAIL_WEBHOOK_URL) return;
  try {
    await fetch(E_MAIL_WEBHOOK_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(E_MAIL_WEBHOOK_SECRET ? { "X-Webhook-Secret": E_MAIL_WEBHOOK_SECRET } : {}),
      },
      body: JSON.stringify({ ereignis, anmeldung, turnier }),
    });
  } catch (e) {
    console.warn("E-Mail-Backend nicht erreichbar, mailto-Fallback wird verwendet.", e);
  }
}

// ---------- Spielplan-Logik ----------

function mischen(liste) {
  const arr = [...liste];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function neuesSpiel(heimId, gastId, extra) {
  return { id: neueId("spiel"), heimId: heimId ?? null, gastId: gastId ?? null, heimTore: null, gastTore: null, ...extra };
}

// Gruppenphase: teilt Teams gleichmäßig in N Gruppen und erzeugt Jeder-gegen-Jeden-Spiele je Gruppe.
function erstelleGruppenplan(teamIds, anzahlGruppen) {
  const teams = mischen(teamIds);
  const gruppen = Array.from({ length: anzahlGruppen }, (_, i) => ({
    id: neueId("gruppe"),
    name: `Gruppe ${String.fromCharCode(65 + i)}`,
    teamIds: [],
  }));
  teams.forEach((teamId, i) => gruppen[i % anzahlGruppen].teamIds.push(teamId));

  const spiele = [];
  gruppen.forEach((g) => {
    for (let i = 0; i < g.teamIds.length; i++) {
      for (let j = i + 1; j < g.teamIds.length; j++) {
        spiele.push(neuesSpiel(g.teamIds[i], g.teamIds[j], { gruppeId: g.id }));
      }
    }
  });

  return { modus: "gruppen", gruppen, spiele, runden: null };
}

// K.o.-System: baut einen Baum mit Runden; nicht besetzte Plätze (bei ungerader Teamzahl) sind Freilose.
function erstelleKoPlan(teamIds) {
  const teams = mischen(teamIds);
  const n = teams.length;
  let groesse = 1;
  while (groesse < n) groesse *= 2;
  const anzahlFreilose = groesse - n;

  const restTeams = [...teams];
  const runde1 = [];
  for (let i = 0; i < groesse / 2; i++) {
    if (i < anzahlFreilose) {
      const heim = restTeams.shift();
      runde1.push(neuesSpiel(heim, null, { freilos: true, sieger: heim }));
    } else {
      const heim = restTeams.shift();
      const gast = restTeams.shift();
      runde1.push(neuesSpiel(heim, gast, { sieger: null }));
    }
  }

  const runden = [runde1];
  let vorherigeAnzahl = runde1.length;
  while (vorherigeAnzahl > 1) {
    const naechsteAnzahl = vorherigeAnzahl / 2;
    runden.push(Array.from({ length: naechsteAnzahl }, () => neuesSpiel(null, null, { sieger: null })));
    vorherigeAnzahl = naechsteAnzahl;
  }

  // Freilose direkt in die nächste Runde durchreichen
  runden[0].forEach((spiel, i) => {
    if (spiel.freilos && runden[1]) {
      const naechsteIdx = Math.floor(i / 2);
      const feld = i % 2 === 0 ? "heimId" : "gastId";
      runden[1][naechsteIdx][feld] = spiel.sieger;
    }
  });

  return { modus: "ko", gruppen: null, spiele: null, runden };
}

// Rechnet aus den Spielergebnissen die Tabelle einer Gruppe (Punkte, Tordifferenz, geschossene Tore).
function berechneTabelle(gruppe, spiele) {
  const stand = {};
  gruppe.teamIds.forEach((id) => {
    stand[id] = { teamId: id, spiele: 0, siege: 0, unentschieden: 0, niederlagen: 0, tore: 0, gegentore: 0, punkte: 0 };
  });
  spiele
    .filter((s) => s.gruppeId === gruppe.id && s.heimTore !== null && s.gastTore !== null)
    .forEach((s) => {
      const heim = stand[s.heimId];
      const gast = stand[s.gastId];
      if (!heim || !gast) return;
      heim.spiele++; gast.spiele++;
      heim.tore += s.heimTore; heim.gegentore += s.gastTore;
      gast.tore += s.gastTore; gast.gegentore += s.heimTore;
      if (s.heimTore > s.gastTore) { heim.siege++; heim.punkte += 3; gast.niederlagen++; }
      else if (s.heimTore < s.gastTore) { gast.siege++; gast.punkte += 3; heim.niederlagen++; }
      else { heim.unentschieden++; gast.unentschieden++; heim.punkte++; gast.punkte++; }
    });
  return Object.values(stand).sort((a, b) => {
    if (b.punkte !== a.punkte) return b.punkte - a.punkte;
    const diffA = a.tore - a.gegentore, diffB = b.tore - b.gegentore;
    if (diffB !== diffA) return diffB - diffA;
    return b.tore - a.tore;
  });
}

// Trägt ein Ergebnis (und bei K.o. den Sieger) in den Plan ein und reicht Sieger ggf. in die nächste Runde durch.
function spielplanMitErgebnis(plan, spielId, heimTore, gastTore, siegerBeiUnentschieden) {
  const neu = JSON.parse(JSON.stringify(plan));

  if (neu.modus === "gruppen") {
    const s = neu.spiele.find((sp) => sp.id === spielId);
    if (s) { s.heimTore = heimTore; s.gastTore = gastTore; }
    return neu;
  }

  // K.o.: Runde und Index des Spiels finden
  for (let r = 0; r < neu.runden.length; r++) {
    const idx = neu.runden[r].findIndex((sp) => sp.id === spielId);
    if (idx === -1) continue;
    const spiel = neu.runden[r][idx];
    spiel.heimTore = heimTore;
    spiel.gastTore = gastTore;
    if (heimTore > gastTore) spiel.sieger = spiel.heimId;
    else if (gastTore > heimTore) spiel.sieger = spiel.gastId;
    else spiel.sieger = siegerBeiUnentschieden || null;

    if (spiel.sieger && neu.runden[r + 1]) {
      const naechsteIdx = Math.floor(idx / 2);
      const feld = idx % 2 === 0 ? "heimId" : "gastId";
      neu.runden[r + 1][naechsteIdx][feld] = spiel.sieger;
    }
    break;
  }
  return neu;
}

// Erstellt clientseitig ein einfaches, druckbares PDF des aktuellen Spielplans (ohne Server).
function spielplanAlsPdfHerunterladen(plan, teams, turnier) {
  const teamName = (id) => {
    if (!id) return "Freilos";
    const t = teams.find((a) => a.id === id);
    return t ? t.verein : "–";
  };

  const doc = new jsPDF();
  const seitenHoehe = doc.internal.pageSize.getHeight();
  let y = 18;

  const neueZeilePruefen = (hoehe = 7) => {
    if (y + hoehe > seitenHoehe - 15) {
      doc.addPage();
      y = 18;
    }
  };

  doc.setFontSize(16);
  doc.text(`Spielplan: ${turnier.name}`, 14, y);
  y += 7;
  doc.setFontSize(10);
  doc.setTextColor(90, 90, 90);
  doc.text(`${formatDatum(turnier.datum)} · ${turnier.ort}`, 14, y);
  doc.setTextColor(0, 0, 0);
  y += 10;

  if (plan.modus === "gruppen") {
    plan.gruppen.forEach((g) => {
      neueZeilePruefen(10);
      doc.setFontSize(13);
      doc.text(g.name, 14, y);
      y += 7;

      const tabelle = berechneTabelle(g, plan.spiele);
      doc.setFontSize(9);
      doc.text("Verein", 14, y);
      doc.text("Sp", 90, y);
      doc.text("S", 102, y);
      doc.text("U", 112, y);
      doc.text("N", 122, y);
      doc.text("Tore", 132, y);
      doc.text("Pkt", 155, y);
      y += 5;
      tabelle.forEach((r) => {
        neueZeilePruefen();
        doc.text(String(teamName(r.teamId)).slice(0, 32), 14, y);
        doc.text(String(r.spiele), 90, y);
        doc.text(String(r.siege), 102, y);
        doc.text(String(r.unentschieden), 112, y);
        doc.text(String(r.niederlagen), 122, y);
        doc.text(`${r.tore}:${r.gegentore}`, 132, y);
        doc.text(String(r.punkte), 155, y);
        y += 5.5;
      });
      y += 3;

      const spieleDerGruppe = plan.spiele.filter((s) => s.gruppeId === g.id);
      spieleDerGruppe.forEach((s) => {
        neueZeilePruefen();
        const ergebnis = s.heimTore !== null && s.gastTore !== null ? `${s.heimTore} : ${s.gastTore}` : "– : –";
        doc.text(`${teamName(s.heimId)}  ${ergebnis}  ${teamName(s.gastId)}`, 14, y);
        y += 5.5;
      });
      y += 6;
    });
  } else {
    plan.runden.forEach((runde, i) => {
      neueZeilePruefen(10);
      const titel = i === plan.runden.length - 1 ? "Finale" : i === plan.runden.length - 2 ? "Halbfinale" : `Runde ${i + 1}`;
      doc.setFontSize(13);
      doc.text(titel, 14, y);
      y += 7;
      doc.setFontSize(9);
      runde.forEach((s) => {
        neueZeilePruefen();
        if (s.freilos) {
          doc.text(`${teamName(s.heimId)}  –  Freilos`, 14, y);
        } else {
          const ergebnis = s.heimTore !== null && s.gastTore !== null ? `${s.heimTore} : ${s.gastTore}` : "– : –";
          doc.text(`${teamName(s.heimId)}  ${ergebnis}  ${teamName(s.gastId)}`, 14, y);
        }
        y += 5.5;
      });
      y += 6;
    });
  }

  doc.save(`spielplan-${turnier.name.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.pdf`);
}

// Erstellt clientseitig einen einfachen Zahlungsbeleg als PDF. Das ist eine Bestätigung/
// Quittung für die eigenen Unterlagen des Vereins - kein formales Rechnungsdokument mit
// USt-Pflichtangaben (falls sowas gebraucht wird, ist das ein separates Thema).
function zahlungsBelegHerunterladen(anmeldung, turnier) {
  const doc = new jsPDF();
  let y = 20;

  doc.setFontSize(18);
  doc.text("Zahlungsbestätigung", 14, y);
  y += 12;

  doc.setFontSize(10);
  doc.setTextColor(90, 90, 90);
  doc.text(`Ausgestellt am: ${formatDatum(new Date().toISOString())}`, 14, y);
  y += 6;
  doc.text(`Beleg-/Referenznummer: ${anmeldung.id}`, 14, y);
  doc.setTextColor(0, 0, 0);
  y += 12;

  doc.setFontSize(11);
  doc.text("Veranstalter", 14, y);
  y += 6;
  doc.setFontSize(9.5);
  doc.text(VERANSTALTER.name, 14, y); y += 5;
  doc.text(VERANSTALTER.anschrift, 14, y); y += 5;
  doc.text(`${VERANSTALTER.email} · ${VERANSTALTER.telefon}`, 14, y);
  y += 12;

  doc.setFontSize(11);
  doc.text("Turnier", 14, y);
  y += 6;
  doc.setFontSize(9.5);
  doc.text(turnier.name, 14, y); y += 5;
  doc.text(`${formatDatum(turnier.datum)} · ${turnier.ort}`, 14, y);
  y += 12;

  doc.setFontSize(11);
  doc.text("Zahlungspflichtige Mannschaft", 14, y);
  y += 6;
  doc.setFontSize(9.5);
  doc.text(`Verein: ${anmeldung.verein}`, 14, y); y += 5;
  doc.text(`Trainer: ${anmeldung.trainer}`, 14, y); y += 5;
  doc.text(`Jahrgang/Jugend: ${anmeldung.jahrgang} / ${anmeldung.jugend}`, 14, y);
  y += 14;

  doc.setDrawColor(200, 200, 200);
  doc.line(14, y, 196, y);
  y += 10;

  doc.setFontSize(12);
  doc.text("Startgebühr", 14, y);
  doc.text(`${turnier.preis.toFixed(2)} €`, 160, y);
  y += 10;

  doc.setFontSize(10);
  doc.setTextColor(30, 110, 60);
  doc.text(`Status: Zahlung bestätigt${anmeldung.bestaetigtAm ? " am " + formatDatumZeit(anmeldung.bestaetigtAm) : ""}`, 14, y);
  doc.setTextColor(0, 0, 0);
  y += 14;

  doc.setFontSize(8.5);
  doc.setTextColor(120, 120, 120);
  doc.text("Dies ist eine Zahlungsbestätigung für eure Unterlagen, kein formales Rechnungsdokument.", 14, y);

  doc.save(`zahlungsbeleg-${anmeldung.verein.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.pdf`);
}

// ---------- Supabase-Anbindung ----------
//
// Statt der Claude-eigenen window.storage-Funktion nutzt die App jetzt eine echte,
// eigenständige Datenbank (Supabase/Postgres). Die Kommunikation läuft über einfache
// fetch()-Aufrufe gegen die REST- und Auth-API von Supabase - kein zusätzliches Paket
// nötig, funktioniert überall dort, wo die App am Ende läuft (Claude-Vorschau, eigene
// Website, etc.).

const SUPABASE_URL = "https://uncltpatrpvsvczwqfdv.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_yN5Ihr6Dc2F_veswAZ9hUQ_mnLDKnIF";

function supabaseHeaders(accessToken) {
  return {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${accessToken || SUPABASE_ANON_KEY}`,
    "Content-Type": "application/json",
  };
}

async function supabaseFehlerText(res) {
  try {
    const daten = await res.json();
    return daten.message || daten.error_description || daten.msg || JSON.stringify(daten);
  } catch {
    return res.statusText;
  }
}

async function supabaseSelect(table, query, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}${query || "?select=*"}`, {
    headers: supabaseHeaders(accessToken),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  return res.json();
}

async function supabaseInsert(table, daten, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, {
    method: "POST",
    headers: { ...supabaseHeaders(accessToken), Prefer: "return=representation" },
    body: JSON.stringify(daten),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  return res.json();
}

async function supabaseUpdate(table, id, daten, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`, {
    method: "PATCH",
    headers: { ...supabaseHeaders(accessToken), Prefer: "return=representation" },
    body: JSON.stringify(daten),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  return res.json();
}

async function supabaseDelete(table, id, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`, {
    method: "DELETE",
    headers: supabaseHeaders(accessToken),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
}

// Für Löschungen, deren Filter keine einfache "id"-Spalte ist (z. B. "alle Anmeldungen eines Turniers").
async function supabaseDeleteWhere(table, query, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}${query}`, {
    method: "DELETE",
    headers: supabaseHeaders(accessToken),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
}

async function supabaseRpc(fnName, parameter, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/${fnName}`, {
    method: "POST",
    headers: supabaseHeaders(accessToken),
    body: JSON.stringify(parameter || {}),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

// -- Supabase Storage (für Dokumente/Dateien) --

const DOKUMENTE_BUCKET = "dokumente";

async function supabaseDateiHochladen(pfad, datei, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${DOKUMENTE_BUCKET}/${pfad}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": datei.type || "application/octet-stream",
    },
    body: datei,
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  return res.json();
}

async function supabaseDateiLoeschen(pfad, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${DOKUMENTE_BUCKET}/${pfad}`, {
    method: "DELETE",
    headers: supabaseHeaders(accessToken),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
}

function dateiOeffentlicheUrl(pfad) {
  return `${SUPABASE_URL}/storage/v1/object/public/${DOKUMENTE_BUCKET}/${pfad}`;
}

// -- Supabase Auth (für Admin-Login) --

async function supabaseAnmelden(email, passwort) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password: passwort }),
  });
  const daten = await res.json();
  if (!res.ok) throw new Error(daten.error_description || daten.msg || "Anmeldung fehlgeschlagen");
  return daten; // { access_token, refresh_token, user }
}

async function supabaseAbmelden(accessToken) {
  try {
    await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
      method: "POST",
      headers: supabaseHeaders(accessToken),
    });
  } catch {
    // Abmelden schlägt in seltenen Fällen fehl (z. B. Token schon abgelaufen) -
    // lokal wird die Sitzung trotzdem beendet, daher hier kein harter Fehler nötig.
  }
}

async function supabasePasswortAendern(accessToken, neuesPasswort) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
    method: "PUT",
    headers: supabaseHeaders(accessToken),
    body: JSON.stringify({ password: neuesPasswort }),
  });
  if (!res.ok) throw new Error(await supabaseFehlerText(res));
  return res.json();
}

const MAX_FEHLVERSUCHE = 5;
const SPERR_DAUER_MS = 60 * 1000;

// ---------- Umwandlung zwischen Datenbank (snake_case) und App (camelCase) ----------

function turnierAusDb(t) {
  return {
    id: t.id, name: t.name, datum: t.datum, ort: t.ort,
    maxPlaetze: t.max_plaetze, preis: Number(t.preis), zahlLink: t.zahl_link,
    erstelltAm: t.erstellt_am ? new Date(t.erstellt_am).getTime() : Date.now(),
  };
}
function turnierZuDb(t) {
  return { id: t.id, name: t.name, datum: t.datum, ort: t.ort, max_plaetze: t.maxPlaetze, preis: t.preis, zahl_link: t.zahlLink || null };
}

function anmeldungAusDb(a) {
  return {
    id: a.id, turnierId: a.turnier_id, verein: a.verein, trainer: a.trainer, jahrgang: a.jahrgang, jugend: a.jugend,
    email: a.email, telefon: a.telefon, notfallkontakt: a.notfallkontakt,
    angemeldetAm: a.angemeldet_am ? new Date(a.angemeldet_am).getTime() : Date.now(),
    frist: a.frist ? new Date(a.frist).getTime() : null,
    status: a.status, zahlungsreferenz: a.zahlungsreferenz, fotoEinverstaendnis: a.foto_einverstaendnis,
    datenschutzAkzeptiertAm: a.datenschutz_akzeptiert_am, teilnahmebedingungenAkzeptiertAm: a.teilnahmebedingungen_akzeptiert_am,
    bearbeitetVon: a.bearbeitet_von,
    bestaetigtAm: a.bestaetigt_am ? new Date(a.bestaetigt_am).getTime() : null,
  };
}
function anmeldungZuDb(a) {
  return {
    id: a.id, turnier_id: a.turnierId, verein: a.verein, trainer: a.trainer, jahrgang: a.jahrgang, jugend: a.jugend,
    email: a.email, telefon: a.telefon, notfallkontakt: a.notfallkontakt || null,
    frist: a.frist ? new Date(a.frist).toISOString() : null,
    status: a.status, foto_einverstaendnis: !!a.fotoEinverstaendnis,
  };
}

function spielplanAusDb(p) {
  return { id: p.id, turnierId: p.turnier_id, modus: p.modus, gruppen: p.gruppen, spiele: p.spiele, runden: p.runden, erstelltAm: p.erstellt_am };
}
function spielplanZuDb(p) {
  return { id: p.id, turnier_id: p.turnierId, modus: p.modus, gruppen: p.gruppen || null, spiele: p.spiele || null, runden: p.runden || null };
}

function dokumentAusDb(d) {
  return {
    id: d.id, turnierId: d.turnier_id, titel: d.titel, dateiname: d.dateiname, pfad: d.pfad,
    typ: d.typ, groesse: d.groesse, hochgeladenAm: d.hochgeladen_am ? new Date(d.hochgeladen_am).getTime() : Date.now(),
    hochgeladenVon: d.hochgeladen_von,
  };
}
function dokumentZuDb(d) {
  return { id: d.id, turnier_id: d.turnierId || null, titel: d.titel, dateiname: d.dateiname, pfad: d.pfad, typ: d.typ, groesse: d.groesse, hochgeladen_von: d.hochgeladenVon || null };
}

// ---------- Hauptkomponente ----------

export default function App() {
  const [ansicht, setAnsicht] = useState("teilnehmer");
  const [turniere, setTurniere] = useState([]);
  const [anmeldungen, setAnmeldungen] = useState([]);
  const [spielplaene, setSpielplaene] = useState([]);
  const [dokumente, setDokumente] = useState([]);
  const [geladen, setGeladen] = useState(false);
  const [ladeFehler, setLadeFehler] = useState("");
  const [jetzt, setJetzt] = useState(Date.now());

  // Deep-Link-Ziel aus der URL lesen, z. B. ?turnier=turnier_abc&ansicht=spielplan (für QR-Codes)
  const [deepLink] = useState(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const turnierId = params.get("turnier");
      const zielAnsicht = params.get("ansicht");
      return turnierId ? { turnierId, ansicht: zielAnsicht || null } : null;
    } catch {
      return null;
    }
  });

  const allesNeuLaden = useCallback(async () => {
    try {
      const [t, a, s, d] = await Promise.all([
        supabaseSelect("turniere", "?select=*&order=datum.asc"),
        supabaseSelect("anmeldungen", "?select=*"),
        supabaseSelect("spielplaene", "?select=*"),
        supabaseSelect("dokumente", "?select=*&order=hochgeladen_am.desc"),
      ]);
      setTurniere(t.map(turnierAusDb));
      setAnmeldungen(a.map(anmeldungAusDb));
      setSpielplaene(s.map(spielplanAusDb));
      setDokumente(d.map(dokumentAusDb));
      setLadeFehler("");
    } catch (e) {
      setLadeFehler("Daten konnten nicht geladen werden: " + e.message);
    } finally {
      setGeladen(true);
    }
  }, []);

  useEffect(() => { allesNeuLaden(); }, [allesNeuLaden]);

  useEffect(() => {
    const iv = setInterval(() => setJetzt(Date.now()), 30000);
    return () => clearInterval(iv);
  }, []);

  const belegtePlaetze = useCallback((turnierId) => {
    return anmeldungen.filter(
      (a) => a.turnierId === turnierId && ["ausstehend", "zahlung_gemeldet", "bestaetigt"].includes(effektiverStatus(a, jetzt))
    ).length;
  }, [anmeldungen, jetzt]);

  if (!geladen) {
    return (
      <div style={{ padding: 40, textAlign: "center", fontFamily: "Inter, sans-serif", color: "#12261B" }}>
        Lädt …
      </div>
    );
  }

  return (
    <div className="kc-root">
      <style>{CSS}</style>
      <header className="kc-header">
        <img className="kc-logo-img" src={LOGO_SRC} alt="KIDZCUP – Football Tournament" />
        <nav className="kc-nav">
          <button className={ansicht === "teilnehmer" ? "kc-chip kc-chip--active" : "kc-chip"} onClick={() => setAnsicht("teilnehmer")}>
            Anmeldung
          </button>
          <button className={ansicht === "admin" ? "kc-chip kc-chip--active" : "kc-chip"} onClick={() => setAnsicht("admin")}>
            Admin
          </button>
        </nav>
      </header>

      {ladeFehler && <div className="kc-fehler" style={{ margin: "12px 18px" }}>{ladeFehler}</div>}

      <main className="kc-main">
        {ansicht === "teilnehmer" ? (
          <TeilnehmerAnsicht
            turniere={turniere}
            anmeldungen={anmeldungen}
            setAnmeldungen={setAnmeldungen}
            belegtePlaetze={belegtePlaetze}
            spielplaene={spielplaene}
            dokumente={dokumente}
            deepLink={deepLink}
            jetzt={jetzt}
          />
        ) : (
          <AdminAnsicht
            turniere={turniere}
            setTurniere={setTurniere}
            anmeldungen={anmeldungen}
            setAnmeldungen={setAnmeldungen}
            spielplaene={spielplaene}
            setSpielplaene={setSpielplaene}
            dokumente={dokumente}
            setDokumente={setDokumente}
            belegtePlaetze={belegtePlaetze}
            jetzt={jetzt}
            neuLaden={allesNeuLaden}
          />
        )}
      </main>

      <footer className="kc-footer">KIDZCUP · Football Tournament</footer>
    </div>
  );
}

// ---------- Teilnehmer-Ansicht ----------

function TeilnehmerAnsicht({ turniere, anmeldungen, setAnmeldungen, belegtePlaetze, spielplaene, dokumente, deepLink, jetzt }) {
  const [ausgewaehlt, setAusgewaehlt] = useState(null);
  const [neueAnmeldung, setNeueAnmeldung] = useState(null); // frisch angelegte Anmeldung dieser Sitzung
  const [codeSuche, setCodeSuche] = useState("");
  const [gefundeneAnmeldung, setGefundeneAnmeldung] = useState(null);
  const [suchFehler, setSuchFehler] = useState("");
  const [angezeigterSpielplan, setAngezeigterSpielplan] = useState(null); // Turnier, dessen Plan gerade angezeigt wird
  const [angezeigteDokumenteFuer, setAngezeigteDokumenteFuer] = useState(null); // Turnier-Objekt oder "allgemein"
  const [wirdGespeichert, setWirdGespeichert] = useState(false);

  // Deep-Link per QR-Code: direkt den Spielplan eines bestimmten Turniers öffnen
  useEffect(() => {
    if (!deepLink || !deepLink.turnierId) return;
    const t = turniere.find((tt) => tt.id === deepLink.turnierId);
    if (t && deepLink.ansicht === "spielplan") setAngezeigterSpielplan(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [turniere.length]);

  const kommendeTurniere = useMemo(
    () => turniere
      .filter((t) => turnierFuerTeilnehmerSichtbar(t, jetzt))
      .sort((a, b) => new Date(a.datum) - new Date(b.datum)),
    [turniere, jetzt]
  );

  const anmeldenBei = async (turnier, daten) => {
    setWirdGespeichert(true);
    try {
      const jetztTs = Date.now();
      const frei = turnier.maxPlaetze - belegtePlaetze(turnier.id);
      const aufWarteliste = frei <= 0;
      const neu = {
        id: neueId("anm"),
        turnierId: turnier.id,
        ...daten,
        angemeldetAm: jetztTs,
        frist: aufWarteliste ? null : jetztTs + DREI_TAGE_MS,
        status: aufWarteliste ? "warteliste" : "ausstehend",
      };
      const gespeichert = await supabaseRpc("oeffentliche_anmeldung_erstellen", { p_daten: anmeldungZuDb(neu) });
      const anmeldung = anmeldungAusDb(gespeichert);
      setAnmeldungen((prev) => [...prev, anmeldung]);
      setNeueAnmeldung(anmeldung);
      setAusgewaehlt(null);
    } catch (e) {
      alert("Anmeldung konnte nicht gespeichert werden: " + e.message);
    } finally {
      setWirdGespeichert(false);
    }
  };

  const alsBezahltMelden = async (anmeldungId, zahlungsreferenz) => {
    try {
      const ergebnis = await supabaseRpc("oeffentlich_als_bezahlt_melden", { p_code: anmeldungId, p_referenz: zahlungsreferenz || "" });
      if (!ergebnis) { alert("Diese Anmeldung konnte nicht aktualisiert werden (evtl. Status bereits geändert)."); return; }
      const aktualisierteAnmeldung = anmeldungAusDb(ergebnis);
      setAnmeldungen((prev) => prev.map((a) => (a.id === anmeldungId ? aktualisierteAnmeldung : a)));
      if (neueAnmeldung && neueAnmeldung.id === anmeldungId) setNeueAnmeldung(aktualisierteAnmeldung);
      if (gefundeneAnmeldung && gefundeneAnmeldung.id === anmeldungId) setGefundeneAnmeldung(aktualisierteAnmeldung);
    } catch (e) {
      alert("Fehler: " + e.message);
    }
  };

  // Art. 7 Abs. 3 DSGVO: Einwilligung muss so einfach widerrufbar sein, wie sie erteilt wurde.
  const fotoEinverstaendnisWiderrufen = async (anmeldungId) => {
    try {
      const ergebnis = await supabaseRpc("oeffentlich_foto_widerrufen", { p_code: anmeldungId });
      const aktualisierteAnmeldung = anmeldungAusDb(ergebnis);
      setAnmeldungen((prev) => prev.map((a) => (a.id === anmeldungId ? aktualisierteAnmeldung : a)));
      if (neueAnmeldung && neueAnmeldung.id === anmeldungId) setNeueAnmeldung(aktualisierteAnmeldung);
      if (gefundeneAnmeldung && gefundeneAnmeldung.id === anmeldungId) setGefundeneAnmeldung(aktualisierteAnmeldung);
    } catch (e) {
      alert("Fehler: " + e.message);
    }
  };

  // Art. 17 DSGVO: Recht auf Löschung. Der Anmeldecode dient dabei als Nachweis der Berechtigung
  // (vergleichbar einem Passwort) – nur wer ihn kennt, kann die zugehörige Anmeldung löschen.
  const anmeldungLoeschen = async (anmeldungId) => {
    try {
      await supabaseRpc("oeffentlich_anmeldung_loeschen", { p_code: anmeldungId });
      setAnmeldungen((prev) => prev.filter((a) => a.id !== anmeldungId));
      setNeueAnmeldung(null);
      setGefundeneAnmeldung(null);
      setCodeSuche("");
    } catch (e) {
      alert("Fehler beim Löschen: " + e.message);
    }
  };

  const codeAbfragen = async () => {
    setSuchFehler("");
    try {
      const treffer = await supabaseRpc("oeffentliche_anmeldung_per_code", { p_code: codeSuche.trim() });
      if (!treffer) {
        setSuchFehler("Kein Anmeldecode gefunden. Bitte prüfe die Eingabe.");
        setGefundeneAnmeldung(null);
        return;
      }
      setGefundeneAnmeldung(anmeldungAusDb(treffer));
    } catch (e) {
      setSuchFehler("Fehler bei der Suche: " + e.message);
    }
  };

  // Bestätigungsansicht nach frischer Anmeldung
  if (neueAnmeldung) {
    const turnier = turniere.find((t) => t.id === neueAnmeldung.turnierId);
    return (
      <AnmeldeStatusKarte
        anmeldung={neueAnmeldung}
        turnier={turnier}
        jetzt={jetzt}
        alsBezahltMelden={alsBezahltMelden}
        fotoEinverstaendnisWiderrufen={fotoEinverstaendnisWiderrufen}
        anmeldungLoeschen={anmeldungLoeschen}
        zeigeSchliessen
        onSchliessen={() => setNeueAnmeldung(null)}
      />
    );
  }

  if (gefundeneAnmeldung) {
    const turnier = turniere.find((t) => t.id === gefundeneAnmeldung.turnierId);
    return (
      <AnmeldeStatusKarte
        anmeldung={gefundeneAnmeldung}
        turnier={turnier}
        jetzt={jetzt}
        alsBezahltMelden={alsBezahltMelden}
        fotoEinverstaendnisWiderrufen={fotoEinverstaendnisWiderrufen}
        anmeldungLoeschen={anmeldungLoeschen}
        zeigeSchliessen
        onSchliessen={() => { setGefundeneAnmeldung(null); setCodeSuche(""); }}
      />
    );
  }

  if (ausgewaehlt) {
    return (
      <AnmeldeFormular
        turnier={ausgewaehlt}
        belegtePlaetze={belegtePlaetze(ausgewaehlt.id)}
        anmeldungen={anmeldungen}
        jetzt={jetzt}
        onAbbrechen={() => setAusgewaehlt(null)}
        onAbsenden={(daten) => anmeldenBei(ausgewaehlt, daten)}
      />
    );
  }

  if (angezeigterSpielplan) {
    const plan = spielplaene.find((p) => p.turnierId === angezeigterSpielplan.id);
    return (
      <div className="kc-section">
        <button className="kc-zurueck" onClick={() => setAngezeigterSpielplan(null)}>← Zurück zur Turnierliste</button>
        <h1 className="kc-h1">Spielplan: {angezeigterSpielplan.name}</h1>
        {plan ? (
          <SpielplanAnzeige plan={plan} teams={anmeldungen} turnier={angezeigterSpielplan} bearbeitbar={false} />
        ) : (
          <p className="kc-sub">Für dieses Turnier wurde noch kein Spielplan erstellt.</p>
        )}
      </div>
    );
  }

  if (angezeigteDokumenteFuer) {
    const istAllgemein = angezeigteDokumenteFuer === "allgemein";
    const liste = dokumente.filter((d) => (istAllgemein ? !d.turnierId : d.turnierId === angezeigteDokumenteFuer.id));
    return (
      <div className="kc-section">
        <button className="kc-zurueck" onClick={() => setAngezeigteDokumenteFuer(null)}>← Zurück</button>
        <h1 className="kc-h1">{istAllgemein ? "Allgemeine Dokumente" : `Dokumente: ${angezeigteDokumenteFuer.name}`}</h1>
        <DokumenteListe dokumente={liste} />
      </div>
    );
  }

  return (
    <div>
      <section className="kc-section">
        <h1 className="kc-h1">Turnier auswählen</h1>
        <p className="kc-sub">Freie Plätze, Termin und Ort auf einen Blick – Anmeldegebühr wird per Link bezahlt.</p>
      </section>

      {kommendeTurniere.length === 0 && (
        <div className="kc-empty">Aktuell sind keine Turniere ausgeschrieben. Schau bald wieder vorbei.</div>
      )}

      <div className="kc-liste">
        {kommendeTurniere.map((t) => {
          const belegt = belegtePlaetze(t.id);
          const frei = Math.max(0, t.maxPlaetze - belegt);
          return (
            <div className="kc-karte" key={t.id} style={{ borderLeftColor: frei === 0 ? "var(--kc-gold)" : "var(--kc-green)" }}>
              <div className="kc-karte__kopf">
                <h2 className="kc-karte__titel">{t.name}</h2>
                <div className="kc-karte__zahl">
                  <span className="kc-zahl-gross">{frei}</span>
                  <span className="kc-zahl-label">Plätze frei</span>
                </div>
              </div>
              <dl className="kc-details">
                <div><dt>Termin</dt><dd>{formatDatum(t.datum)}</dd></div>
                <div><dt>Ort</dt><dd>{t.ort}</dd></div>
                <div><dt>Gebühr</dt><dd>{t.preis} €</dd></div>
              </dl>
              <button className="kc-btn kc-btn--primary" onClick={() => setAusgewaehlt(t)}>
                {frei === 0 ? "Auf Warteliste anmelden" : "Jetzt anmelden"}
              </button>
              {spielplaene.some((p) => p.turnierId === t.id) && (
                <button className="kc-btn kc-btn--sekundaer kc-btn--block" onClick={() => setAngezeigterSpielplan(t)}>
                  Spielplan ansehen
                </button>
              )}
              {dokumente.some((d) => d.turnierId === t.id) && (
                <button className="kc-btn kc-btn--sekundaer kc-btn--block" onClick={() => setAngezeigteDokumenteFuer(t)}>
                  Dokumente ({dokumente.filter((d) => d.turnierId === t.id).length})
                </button>
              )}
            </div>
          );
        })}
      </div>

      {dokumente.some((d) => !d.turnierId) && (
        <section className="kc-section">
          <button className="kc-btn kc-btn--sekundaer kc-btn--block" onClick={() => setAngezeigteDokumenteFuer("allgemein")}>
            Allgemeine Dokumente ({dokumente.filter((d) => !d.turnierId).length})
          </button>
        </section>
      )}

      <section className="kc-section kc-section--code">
        <h2 className="kc-h2">Anmeldestatus abrufen</h2>
        <p className="kc-sub">Gib den Anmeldecode ein, den du nach deiner Anmeldung erhalten hast.</p>
        <div className="kc-code-zeile">
          <input
            className="kc-input"
            placeholder="z. B. anm_m5x3k2_ab12cd"
            value={codeSuche}
            onChange={(e) => setCodeSuche(e.target.value)}
          />
          <button className="kc-btn kc-btn--sekundaer" onClick={codeAbfragen}>Status anzeigen</button>
        </div>
        {suchFehler && <p className="kc-fehler">{suchFehler}</p>}
      </section>
    </div>
  );
}

function DatenschutzText() {
  return (
    <div className="kc-datenschutz-text">
      <p className="kc-ds-hinweis-box">
        <strong>Hinweis für den Veranstalter:</strong> Dieser Text ist ein sorgfältig formulierter Entwurf auf Basis
        der DSGVO-Informationspflichten (Art. 13 DSGVO), aber keine Rechtsberatung. Bitte die Platzhalter in
        eckigen Klammern ausfüllen und den Text vor dem Livegang von einem Anwalt oder Datenschutzbeauftragten
        prüfen lassen.
      </p>

      <strong>1. Verantwortlicher</strong>
      <p>
        {VERANSTALTER.name}<br />
        {VERANSTALTER.anschrift}<br />
        Vertreten durch: {VERANSTALTER.vertreter}<br />
        E-Mail: {VERANSTALTER.email} · Telefon: {VERANSTALTER.telefon}
      </p>

      <strong>2. Welche Daten wir verarbeiten</strong>
      <p>Im Rahmen der Turnieranmeldung erheben wir: Vereinsname, Name der Trainerin/des Trainers, Jahrgang der Mannschaft, E-Mail-Adresse und Telefonnummer der Kontaktperson.</p>

      <strong>3. Zweck und Rechtsgrundlage</strong>
      <p>
        Die Verarbeitung erfolgt zur Durchführung der Turnieranmeldung und Abwicklung der Startgebühr, also zur
        Erfüllung eines Vertrags bzw. zur Durchführung vorvertraglicher Maßnahmen (Art. 6 Abs. 1 lit. b DSGVO).
        Die Kontaktaufnahme per E-Mail zu Frist, Zahlungsstatus oder Turnierablauf beruht auf demselben Zweck.
      </p>

      <strong>4. Empfänger der Daten und Auftragsverarbeitung</strong>
      <p>
        Eine Weitergabe erfolgt nur, soweit dies zur Abwicklung der Zahlung notwendig ist (z. B. an den genutzten
        Zahlungsdienstleister, sobald der Zahlungslink genutzt wird), an mit der Turnierorganisation befasste
        Personen des Veranstalters sowie – falls eingesetzt – an einen Dienstleister für den technischen
        Versand von Bestätigungs-E-Mails. Mit allen eingesetzten Dienstleistern, die dabei in unserem Auftrag
        personenbezogene Daten verarbeiten, bestehen entsprechende Verträge zur Auftragsverarbeitung nach
        Art. 28 DSGVO. Eine Weitergabe zu Werbezwecken findet nicht statt.
      </p>

      <strong>5. Speicherdauer</strong>
      <p>
        Die Daten werden gespeichert, solange dies für die Organisation des jeweiligen Turniers erforderlich ist,
        in der Regel jedoch nicht länger als {AUFBEWAHRUNG_MONATE} Monate nach dem Turniertermin, sofern keine
        gesetzlichen Aufbewahrungspflichten (z. B. handels- oder steuerrechtlich bei Zahlungsbelegen)
        entgegenstehen. Anschließend werden die Daten gelöscht.
      </p>

      <strong>6. Ihre Rechte</strong>
      <p>
        Sie haben das Recht auf Auskunft (Art. 15 DSGVO), Berichtigung (Art. 16), Löschung (Art. 17), Einschränkung
        der Verarbeitung (Art. 18), Datenübertragbarkeit (Art. 20) sowie Widerspruch gegen die Verarbeitung
        (Art. 21). Über Ihren persönlichen Anmeldecode können Sie in der App jederzeit selbst eine erteilte
        Foto-/Video-Einwilligung widerrufen oder Ihre gesamte Anmeldung löschen (Bereich „Meine
        Datenschutzrechte" auf der Statusseite); alternativ wenden Sie sich an die oben genannte
        Kontaktadresse. Außerdem steht Ihnen ein Beschwerderecht bei der zuständigen
        Datenschutz-Aufsichtsbehörde zu.
      </p>

      <strong>7. Freiwilligkeit</strong>
      <p>Die Angabe der Daten ist freiwillig, aber für die Teilnahme am Turnier erforderlich – ohne diese Angaben ist keine Anmeldung möglich.</p>
    </div>
  );
}

function TeilnahmebedingungenText() {
  return (
    <div className="kc-datenschutz-text">
      <p className="kc-ds-hinweis-box">
        <strong>Hinweis für den Veranstalter:</strong> Auch dies ist ein sorgfältig formulierter Entwurf,
        keine Rechtsberatung. Insbesondere Haftungsausschlüsse sind rechtlich nur eingeschränkt wirksam
        (z. B. nie bei Vorsatz oder grober Fahrlässigkeit, bei Personenschäden ohnehin nur sehr begrenzt) –
        bitte vor dem Livegang von einem Anwalt prüfen und die Platzhalter ausfüllen lassen.
      </p>

      <strong>1. Teilnahmeberechtigung</strong>
      <p>Mit der Anmeldung bestätigt die meldende Person, zur Anmeldung der genannten Mannschaft für den angegebenen Verein berechtigt zu sein.</p>

      <strong>2. Ablauf und Anweisungen</strong>
      <p>Die Teilnehmenden verpflichten sich, den Anweisungen der Turnierleitung, Schiedsrichter:innen und Betreuer:innen Folge zu leisten und sich fair und sportlich zu verhalten.</p>

      <strong>3. Haftung</strong>
      <p>
        Die Teilnahme erfolgt auf eigene Gefahr im Rahmen des allgemeinen Lebensrisikos beim Sport.
        {VERANSTALTER.name} haftet nur für Schäden, die auf Vorsatz oder grober Fahrlässigkeit beruhen,
        sowie im Rahmen zwingender gesetzlicher Vorschriften (insbesondere bei Verletzung von Leben, Körper
        oder Gesundheit). Für Wertsachen und persönliche Gegenstände wird keine Haftung übernommen.
      </p>

      <strong>4. Absage oder Abbruch des Turniers</strong>
      <p>
        Muss das Turnier aus wichtigem Grund (z. B. Unwetter, behördliche Anordnung) abgesagt oder
        abgebrochen werden, wird [Rückerstattungsregelung einsetzen, z. B.: die Startgebühr anteilig
        zurückerstattet / ein Gutschein für ein Ersatztermin ausgestellt].
      </p>

      <strong>5. Bild- und Tonaufnahmen</strong>
      <p>Ob Fotos/Videos des Teams verwendet werden dürfen, wird separat über das entsprechende Einverständnis-Kästchen abgefragt und ist nicht Voraussetzung für die Teilnahme.</p>

      <strong>6. Kontakt</strong>
      <p>Bei Fragen zu diesen Teilnahmebedingungen: {VERANSTALTER.email}</p>
    </div>
  );
}

// Übliche Jugend-/Altersklassen im deutschen Amateurfußball, inkl. gängiger 1er-/2er-Unterteilung.
const JUGEND_KATEGORIEN = [
  "Bambini",
  "G1", "G2",
  "F1", "F2",
  "E1", "E2",
  "D1", "D2",
  "C1", "C2",
  "B1", "B2",
  "A1", "A2",
];

function AnmeldeFormular({ turnier, belegtePlaetze, anmeldungen, jetzt, onAbbrechen, onAbsenden }) {
  const [form, setForm] = useState({
    verein: "", trainer: "", jahrgang: "", jugend: "", email: "", telefon: "", notfallkontakt: "",
  });
  const [datenschutzOk, setDatenschutzOk] = useState(false);
  const [zeigeDatenschutz, setZeigeDatenschutz] = useState(false);
  const [teilnahmebedingungenOk, setTeilnahmebedingungenOk] = useState(false);
  const [zeigeTeilnahmebedingungen, setZeigeTeilnahmebedingungen] = useState(false);
  const [fotoEinverstaendnis, setFotoEinverstaendnis] = useState(false);
  const [fehler, setFehler] = useState("");
  const frei = Math.max(0, turnier.maxPlaetze - belegtePlaetze);

  const feld = (name) => (e) => setForm({ ...form, [name]: e.target.value });

  const gueltig =
    form.verein.trim() && form.trainer.trim() && form.jahrgang.trim() && form.jugend.trim() &&
    form.email.trim() && form.telefon.trim() && datenschutzOk && teilnahmebedingungenOk;

  const absenden = (e) => {
    e.preventDefault();
    if (!gueltig) return;
    const vereinNormiert = form.verein.trim().toLowerCase();
    const jugendNormiert = form.jugend.trim().toLowerCase();
    const duplikat = anmeldungen.find(
      (a) => a.turnierId === turnier.id &&
        a.verein.trim().toLowerCase() === vereinNormiert &&
        (a.jugend || "").trim().toLowerCase() === jugendNormiert &&
        !["abgelehnt", "abgelaufen"].includes(effektiverStatus(a, jetzt))
    );
    if (duplikat) {
      setFehler(`"${form.verein}" (${form.jugend}) ist für dieses Turnier bereits angemeldet (Status: ${STATUS_LABEL[effektiverStatus(duplikat, jetzt)]}). Anmeldecode: ${duplikat.id}`);
      return;
    }
    setFehler("");
    onAbsenden({
      ...form,
      fotoEinverstaendnis,
      datenschutzAkzeptiertAm: Date.now(),
      teilnahmebedingungenAkzeptiertAm: Date.now(),
    });
  };

  return (
    <div className="kc-section">
      <button className="kc-zurueck" onClick={onAbbrechen}>← Zurück zur Turnierliste</button>
      <h1 className="kc-h1">Anmeldung: {turnier.name}</h1>
      <p className="kc-sub">
        {formatDatum(turnier.datum)} · {turnier.ort} · {turnier.preis} € Startgebühr · noch {frei} Plätze frei
      </p>

      {frei === 0 && (
        <div className="kc-hinweis kc-hinweis--warteliste">
          Dieses Turnier ist aktuell ausgebucht. Deine Anmeldung landet auf der Warteliste – sobald ein Platz frei wird, wirst du aufgenommen und erhältst ab dann 3 Tage Zeit zur Zahlung.
        </div>
      )}

      <form className="kc-formular" onSubmit={absenden}>
        <label className="kc-feld">
          <span>Verein</span>
          <input className="kc-input" value={form.verein} onChange={feld("verein")} required />
        </label>
        <label className="kc-feld">
          <span>Trainer</span>
          <input className="kc-input" value={form.trainer} onChange={feld("trainer")} required />
        </label>
        <div className="kc-feld-reihe">
          <label className="kc-feld">
            <span>Jahrgang</span>
            <input className="kc-input" type="number" min="2005" max="2026" placeholder="z. B. 2016" value={form.jahrgang} onChange={feld("jahrgang")} required />
          </label>
          <label className="kc-feld">
            <span>Jugend</span>
            <select className="kc-input" value={form.jugend} onChange={feld("jugend")} required>
              <option value="" disabled>Bitte wählen…</option>
              {JUGEND_KATEGORIEN.map((k) => (
                <option key={k} value={k}>{k}</option>
              ))}
            </select>
          </label>
        </div>
        <label className="kc-feld">
          <span>E-Mail</span>
          <input className="kc-input" type="email" value={form.email} onChange={feld("email")} required />
        </label>
        <label className="kc-feld">
          <span>Telefonnummer</span>
          <input className="kc-input" type="tel" value={form.telefon} onChange={feld("telefon")} required />
        </label>
        <label className="kc-feld">
          <span>Notfallkontakt am Turniertag (Name &amp; Telefon, optional)</span>
          <input
            className="kc-input"
            value={form.notfallkontakt}
            onChange={feld("notfallkontakt")}
            placeholder="z. B. Betreuer Max Mustermann, 0170 1234567"
          />
        </label>

        {frei > 0 && (
          <div className="kc-hinweis">
            Nach der Anmeldung hast du <strong>3 Tage</strong> Zeit, die Startgebühr über den bereitgestellten Zahlungslink zu begleichen.
            Ohne fristgerechte Zahlung wird die Teilnahme nicht bestätigt und der Platz wird freigegeben.
          </div>
        )}

        {fehler && <p className="kc-fehler">{fehler}</p>}

        <div className="kc-datenschutz">
          <label className="kc-checkbox-zeile">
            <input type="checkbox" checked={datenschutzOk} onChange={(e) => setDatenschutzOk(e.target.checked)} />
            <span>Ich habe die <button type="button" className="kc-inline-link" onClick={() => setZeigeDatenschutz((v) => !v)}>Datenschutzhinweise</button> gelesen und stimme der Verarbeitung meiner Daten zur Turnieranmeldung zu. *</span>
          </label>
          {zeigeDatenschutz && <DatenschutzText />}
        </div>

        <div className="kc-datenschutz">
          <label className="kc-checkbox-zeile">
            <input type="checkbox" checked={teilnahmebedingungenOk} onChange={(e) => setTeilnahmebedingungenOk(e.target.checked)} />
            <span>Ich habe die <button type="button" className="kc-inline-link" onClick={() => setZeigeTeilnahmebedingungen((v) => !v)}>Teilnahmebedingungen</button> gelesen und akzeptiere sie für unsere Mannschaft. *</span>
          </label>
          {zeigeTeilnahmebedingungen && <TeilnahmebedingungenText />}
        </div>

        <div className="kc-datenschutz">
          <label className="kc-checkbox-zeile">
            <input type="checkbox" checked={fotoEinverstaendnis} onChange={(e) => setFotoEinverstaendnis(e.target.checked)} />
            <span>Wir sind damit einverstanden, dass beim Turnier entstandene Foto- und Videoaufnahmen unseres Teams für Social Media, Website und Presse des Veranstalters verwendet werden dürfen (freiwillig, jederzeit widerrufbar).</span>
          </label>
        </div>

        <p className="kc-notiz">* Pflichtangabe</p>

        <button className="kc-btn kc-btn--primary" type="submit" disabled={!gueltig}>
          {frei > 0 ? "Verbindlich anmelden" : "Auf Warteliste anmelden"}
        </button>
      </form>
    </div>
  );
}

function AnmeldeStatusKarte({ anmeldung, turnier, jetzt, alsBezahltMelden, fotoEinverstaendnisWiderrufen, anmeldungLoeschen, zeigeSchliessen, onSchliessen }) {
  const status = effektiverStatus(anmeldung, jetzt);
  const restMs = anmeldung.frist ? anmeldung.frist - jetzt : null;
  const [zahlungsreferenz, setZahlungsreferenz] = useState("");
  const [zahlungBestaetigt, setZahlungBestaetigt] = useState(false);
  const [zeigeMeineDaten, setZeigeMeineDaten] = useState(false);

  const loeschenBestaetigen = () => {
    if (confirm("Anmeldung wirklich endgültig löschen? Alle gespeicherten Daten zu dieser Anmeldung werden unwiderruflich entfernt. Das kann nicht rückgängig gemacht werden.")) {
      anmeldungLoeschen(anmeldung.id);
    }
  };

  return (
    <div className="kc-section">
      {zeigeSchliessen && <button className="kc-zurueck" onClick={onSchliessen}>← Zurück</button>}
      <div className="kc-status-karte">
        <span className="kc-status-badge" style={{ background: STATUS_FARBE[status] }}>{STATUS_LABEL[status]}</span>
        <h1 className="kc-h1">{turnier ? turnier.name : "Turnier"}</h1>
        <p className="kc-sub">{turnier ? `${formatDatum(turnier.datum)} · ${turnier.ort}` : ""}</p>

        <dl className="kc-details">
          <div><dt>Verein</dt><dd>{anmeldung.verein}</dd></div>
          <div><dt>Trainer</dt><dd>{anmeldung.trainer}</dd></div>
          <div><dt>Jahrgang</dt><dd>{anmeldung.jahrgang}</dd></div>
          <div><dt>Jugend</dt><dd>{anmeldung.jugend}</dd></div>
          {anmeldung.notfallkontakt && <div><dt>Notfallkontakt</dt><dd>{anmeldung.notfallkontakt}</dd></div>}
          <div><dt>Angemeldet am</dt><dd>{formatDatumZeit(anmeldung.angemeldetAm)}</dd></div>
          {anmeldung.frist && <div><dt>Zahlungsfrist</dt><dd>{formatDatumZeit(anmeldung.frist)}</dd></div>}
          {(status === "ausstehend" || status === "zahlung_gemeldet") && restMs !== null && (
            <div><dt>Verbleibende Zeit</dt><dd>{restzeit(restMs)}</dd></div>
          )}
        </dl>

        {status === "ausstehend" && turnier && turnier.zahlLink && (
          <div className="kc-zahl-block">
            <a className="kc-btn kc-btn--primary" href={normalisiereLink(turnier.zahlLink)} target="_blank" rel="noopener">
              Startgebühr jetzt bezahlen ({turnier.preis} €)
            </a>
            <div className="kc-app-tipp">
              💡 Öffnet sich eine App (z. B. PayPal) und findet euer Profil nicht? Link kurz gedrückt halten →
              „Im Browser öffnen" wählen.
            </div>
            <div className="kc-zahlreferenz-zeile">
              <input
                className="kc-input"
                placeholder="Verwendungszweck/Referenz (optional)"
                value={zahlungsreferenz}
                onChange={(e) => setZahlungsreferenz(e.target.value)}
              />
            </div>
            <label className="kc-checkbox-zeile" style={{ marginTop: "10px" }}>
              <input type="checkbox" checked={zahlungBestaetigt} onChange={(e) => setZahlungBestaetigt(e.target.checked)} />
              <span>Ich bestätige, dass ich die Startgebühr von {turnier.preis} € tatsächlich bereits überwiesen habe. Der Veranstalter prüft die Zahlung vor der endgültigen Bestätigung; eine wahrheitswidrige Angabe kann zum Ausschluss vom Turnier führen.</span>
            </label>
            <button
              className="kc-btn kc-btn--sekundaer"
              style={{ marginTop: "10px" }}
              disabled={!zahlungBestaetigt}
              onClick={() => alsBezahltMelden(anmeldung.id, zahlungsreferenz)}
            >
              Ich habe bereits bezahlt
            </button>
          </div>
        )}

        {status === "zahlung_gemeldet" && (
          <p className="kc-hinweis">Danke! Deine Zahlung wird vom Veranstalter geprüft und in Kürze bestätigt.</p>
        )}
        {status === "bestaetigt" && (
          <>
            <p className="kc-hinweis kc-hinweis--erfolg">Deine Teilnahme steht fest – wir freuen uns auf dich beim Turnier!</p>
            {turnier && (
              <button className="kc-btn kc-btn--sekundaer" onClick={() => zahlungsBelegHerunterladen(anmeldung, turnier)}>
                📄 Zahlungsbeleg herunterladen
              </button>
            )}
          </>
        )}
        {status === "abgelaufen" && (
          <p className="kc-hinweis kc-hinweis--fehler">Die Zahlungsfrist ist abgelaufen. Die Teilnahme wurde leider nicht bestätigt.</p>
        )}
        {status === "abgelehnt" && (
          <p className="kc-hinweis kc-hinweis--fehler">Die gemeldete Zahlung wurde nicht bestätigt. Bitte wende dich an den Veranstalter.</p>
        )}
        {status === "warteliste" && (
          <p className="kc-hinweis">Du stehst auf der Warteliste. Sobald ein Platz frei wird, wirst du aufgenommen und erhältst 3 Tage Zeit zur Zahlung – schau mit deinem Anmeldecode gelegentlich wieder vorbei.</p>
        )}

        <div className="kc-code-box">
          Anmeldecode zum Wiederfinden: <code>{anmeldung.id}</code>
        </div>

        <div className="kc-datenschutz-aktionen">
          <button className="kc-inline-link" type="button" onClick={() => setZeigeMeineDaten((v) => !v)}>
            {zeigeMeineDaten ? "Meine Datenschutzrechte ausblenden" : "Meine Datenschutzrechte (Widerruf, Löschung)"}
          </button>
          {zeigeMeineDaten && (
            <div className="kc-datenschutz-text">
              <p>
                Diese Anmeldung ist über deinen Anmeldecode eindeutig dir zugeordnet. Du kannst hier direkt von
                deinen Rechten aus Art. 7 Abs. 3 und Art. 17 DSGVO Gebrauch machen:
              </p>

              {anmeldung.fotoEinverstaendnis ? (
                <div className="kc-admin-aktionen">
                  <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => fotoEinverstaendnisWiderrufen(anmeldung.id)}>
                    Foto-/Video-Einwilligung widerrufen
                  </button>
                </div>
              ) : (
                <p className="kc-notiz">Foto-/Video-Einwilligung: aktuell nicht erteilt bzw. bereits widerrufen.</p>
              )}

              <p style={{ marginTop: "8px" }}>
                Möchtest du deine gesamte Anmeldung inklusive aller gespeicherten Daten unwiderruflich löschen lassen?
                Das entfernt auch einen bereits bestätigten Turnierplatz.
              </p>
              <div className="kc-admin-aktionen">
                <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={loeschenBestaetigen}>
                  Anmeldung endgültig löschen
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ---------- Admin-Ansicht ----------

// Zeigt einen Spielplan (Gruppenphase oder K.o.) an. Im bearbeitbaren Modus können Ergebnisse
// eingetragen werden; sonst ist es eine reine Lese-Ansicht für Teilnehmer.
function SpielplanAnzeige({ plan, teams, turnier, bearbeitbar, onSpielSpeichern }) {
  const teamName = (id) => {
    if (!id) return "Freilos";
    const t = teams.find((a) => a.id === id);
    return t ? t.verein : "–";
  };

  const inhalt = plan.modus === "gruppen" ? (
    <div className="kc-spielplan">
      {plan.gruppen.map((g) => {
        const tabelle = berechneTabelle(g, plan.spiele);
        const spieleDerGruppe = plan.spiele.filter((s) => s.gruppeId === g.id);
        return (
          <div className="kc-gruppe-block" key={g.id}>
            <h3 className="kc-h3">{g.name}</h3>
            <table className="kc-tabelle">
              <thead>
                <tr><th>Verein</th><th>Sp.</th><th>S</th><th>U</th><th>N</th><th>Tore</th><th>Pkt.</th></tr>
              </thead>
              <tbody>
                {tabelle.map((r) => (
                  <tr key={r.teamId}>
                    <td>{teamName(r.teamId)}</td>
                    <td>{r.spiele}</td>
                    <td>{r.siege}</td>
                    <td>{r.unentschieden}</td>
                    <td>{r.niederlagen}</td>
                    <td>{r.tore}:{r.gegentore}</td>
                    <td><strong>{r.punkte}</strong></td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="kc-spiele-liste">
              {spieleDerGruppe.map((s) => (
                <SpielZeile key={s.id} spiel={s} teamName={teamName} bearbeitbar={bearbeitbar} onSpeichern={onSpielSpeichern} />
              ))}
            </div>
          </div>
        );
      })}
    </div>
  ) : (
    // K.o.-System
    <div className="kc-spielplan">
      {plan.runden.map((runde, i) => (
        <div className="kc-runde-block" key={i}>
          <h3 className="kc-h3">
            {i === plan.runden.length - 1 ? "Finale" : i === plan.runden.length - 2 ? "Halbfinale" : `Runde ${i + 1}`}
          </h3>
          <div className="kc-spiele-liste">
            {runde.map((s) => (
              <SpielZeile key={s.id} spiel={s} teamName={teamName} bearbeitbar={bearbeitbar && !s.freilos} onSpeichern={onSpielSpeichern} zeigeSieger />
            ))}
          </div>
        </div>
      ))}
    </div>
  );

  return (
    <div>
      {turnier && (
        <div className="kc-spielplan-aktionen">
          <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => spielplanAlsPdfHerunterladen(plan, teams, turnier)}>
            📄 Als PDF herunterladen
          </button>
        </div>
      )}
      {inhalt}
    </div>
  );
}

function SpielZeile({ spiel, teamName, bearbeitbar, onSpeichern, zeigeSieger }) {
  const [heim, setHeim] = useState(spiel.heimTore ?? "");
  const [gast, setGast] = useState(spiel.gastTore ?? "");
  const [siegerWahl, setSiegerWahl] = useState("");
  const hatErgebnis = spiel.heimTore !== null && spiel.gastTore !== null;
  const wartetAufTeams = !spiel.heimId || !spiel.gastId;

  if (spiel.freilos) {
    return (
      <div className="kc-spiel-zeile kc-spiel-zeile--freilos">
        <span>{teamName(spiel.heimId)}</span><span className="kc-notiz">Freilos</span>
      </div>
    );
  }

  const speichern = () => {
    const h = Number(heim), g = Number(gast);
    if (Number.isNaN(h) || Number.isNaN(g) || heim === "" || gast === "") return;
    if (zeigeSieger && h === g && !siegerWahl) return; // bei K.o. muss ein Sieger feststehen
    onSpeichern(spiel.id, h, g, siegerWahl || null);
  };

  return (
    <div className="kc-spiel-zeile">
      <span className={zeigeSieger && spiel.sieger === spiel.heimId ? "kc-team-sieger" : ""}>{teamName(spiel.heimId)}</span>
      {bearbeitbar && !wartetAufTeams ? (
        <div className="kc-spiel-eingabe">
          <input className="kc-input kc-input--klein" type="number" min="0" value={heim} onChange={(e) => setHeim(e.target.value)} />
          <span>:</span>
          <input className="kc-input kc-input--klein" type="number" min="0" value={gast} onChange={(e) => setGast(e.target.value)} />
        </div>
      ) : (
        <span className="kc-spiel-ergebnis">{hatErgebnis ? `${spiel.heimTore} : ${spiel.gastTore}` : wartetAufTeams ? "offen" : "– : –"}</span>
      )}
      <span className={zeigeSieger && spiel.sieger === spiel.gastId ? "kc-team-sieger" : ""}>{teamName(spiel.gastId)}</span>
      {bearbeitbar && !wartetAufTeams && (
        <div className="kc-spiel-aktionen">
          {zeigeSieger && heim !== "" && gast !== "" && Number(heim) === Number(gast) && (
            <select className="kc-input kc-input--klein" value={siegerWahl} onChange={(e) => setSiegerWahl(e.target.value)}>
              <option value="">Sieger bei Unentschieden…</option>
              <option value={spiel.heimId}>{teamName(spiel.heimId)}</option>
              <option value={spiel.gastId}>{teamName(spiel.gastId)}</option>
            </select>
          )}
          <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={speichern}>Speichern</button>
        </div>
      )}
    </div>
  );
}

// Erstellungs-Dialog: Modus frei wählbar (Gruppenphase oder K.o.-System), inkl. Anzahl Gruppen.
function SpielplanErstellen({ bestaetigteTeams, onErstellen }) {
  const [modus, setModus] = useState("gruppen");
  const [anzahlGruppen, setAnzahlGruppen] = useState(2);
  const anzahlTeams = bestaetigteTeams.length;
  const zuWenigTeams = anzahlTeams < 2;

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">Spielplan erstellen</h2>
      <p className="kc-sub">{anzahlTeams} bestätigte Mannschaft{anzahlTeams !== 1 ? "en" : ""} verfügbar.</p>
      {zuWenigTeams ? (
        <p className="kc-notiz">Es werden mindestens 2 bestätigte Mannschaften benötigt, um einen Spielplan zu erstellen.</p>
      ) : (
        <div className="kc-formular">
          <label className="kc-feld">
            <span>Turnierformat</span>
            <select className="kc-input" value={modus} onChange={(e) => setModus(e.target.value)}>
              <option value="gruppen">Gruppenphase (jeder gegen jeden)</option>
              <option value="ko">K.o.-System</option>
            </select>
          </label>
          {modus === "gruppen" && (
            <label className="kc-feld">
              <span>Anzahl Gruppen</span>
              <input
                className="kc-input"
                type="number"
                min="1"
                max={Math.max(1, Math.floor(anzahlTeams / 2))}
                value={anzahlGruppen}
                onChange={(e) => setAnzahlGruppen(Number(e.target.value))}
              />
            </label>
          )}
          <button
            className="kc-btn kc-btn--primary"
            onClick={() => onErstellen(modus, modus === "gruppen" ? anzahlGruppen : null)}
          >
            Spielplan erstellen
          </button>
        </div>
      )}
    </div>
  );
}

function SpielplanVerwaltung({ turnier, anmeldungen, plan, onErstellen, onSpielSpeichern, onNeuErstellen }) {
  const bestaetigteTeams = anmeldungen.filter((a) => a.turnierId === turnier.id && a.status === "bestaetigt");
  const spielplanLink = `${window.location.origin}${window.location.pathname}?turnier=${encodeURIComponent(turnier.id)}&ansicht=spielplan`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(spielplanLink)}`;

  return (
    <div className="kc-section">
      <h2 className="kc-h2">Spielplan: {turnier.name}</h2>
      {!plan ? (
        <SpielplanErstellen bestaetigteTeams={bestaetigteTeams} onErstellen={onErstellen} />
      ) : (
        <>
          <div className="kc-admin-aktionen">
            <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={onNeuErstellen}>Spielplan neu erstellen</button>
          </div>

          <div className="kc-qr-block">
            <img src={qrCodeUrl} alt="QR-Code zum Spielplan" width="140" height="140" />
            <div>
              <p className="kc-notiz">QR-Code zum direkten Öffnen des Spielplans – ideal für Aushänge vor Ort oder Flyer.</p>
              <div className="kc-link-zeile">
                <input className="kc-input kc-input--klein" readOnly value={spielplanLink} onClick={(e) => e.target.select()} />
              </div>
            </div>
          </div>

          <SpielplanAnzeige plan={plan} teams={anmeldungen} turnier={turnier} bearbeitbar onSpielSpeichern={onSpielSpeichern} />
        </>
      )}
    </div>
  );
}

function DokumenteListe({ dokumente }) {
  if (dokumente.length === 0) {
    return <p className="kc-notiz">Keine Dokumente vorhanden.</p>;
  }
  return (
    <div className="kc-dokumente-liste">
      {dokumente.map((d) => (
        <a key={d.id} className="kc-dokument-zeile" href={dateiOeffentlicheUrl(d.pfad)} target="_blank" rel="noopener noreferrer">
          <span className="kc-dokument-icon">{d.typ && d.typ.startsWith("image/") ? "🖼️" : "📄"}</span>
          <span className="kc-dokument-info">
            <strong>{d.titel}</strong>
            <span className="kc-notiz">{d.dateiname}{d.groesse ? ` · ${(d.groesse / 1024).toFixed(0)} KB` : ""}</span>
          </span>
          <span className="kc-dokument-download">Herunterladen ↓</span>
        </a>
      ))}
    </div>
  );
}

// Vereinfachte Orientierung für ein Löschkonzept: Personenbezogene Anmeldedaten werden nicht auf
// unbestimmte Zeit vorgehalten. Der Zeitraum ist bewusst konfigurierbar – je nach Verein/Verband
// können andere handels- oder vereinsrechtliche Aufbewahrungspflichten gelten (bitte prüfen lassen).
const AUFBEWAHRUNG_MONATE = 24;

function monateSeitDatum(datumIso) {
  const dann = new Date(datumIso);
  const jetzt = new Date();
  return (jetzt.getFullYear() - dann.getFullYear()) * 12 + (jetzt.getMonth() - dann.getMonth());
}

function AdminAnsicht({ turniere, setTurniere, anmeldungen, setAnmeldungen, spielplaene, setSpielplaene, dokumente, setDokumente, belegtePlaetze, jetzt }) {
  const [session, setSession] = useState(null); // { access_token, user }
  const [adminProfil, setAdminProfil] = useState(null); // Zeile aus admin_profile: { user_id, name, email, erstellt_am }
  const [admins, setAdmins] = useState([]); // alle admin_profile-Einträge, für "Admins verwalten"
  const [profilLaedt, setProfilLaedt] = useState(false);

  const [zeigeFormular, setZeigeFormular] = useState(false);
  const [bearbeitetesTurnier, setBearbeitetesTurnier] = useState(null);
  const [offenesTurnier, setOffenesTurnier] = useState(null);
  const [zeigePasswortAendern, setZeigePasswortAendern] = useState(false);
  const [zeigeAdminsVerwalten, setZeigeAdminsVerwalten] = useState(false);
  const [zeigeDatenschutzTools, setZeigeDatenschutzTools] = useState(false);
  const [zeigeDokumenteVerwalten, setZeigeDokumenteVerwalten] = useState(false);
  const [offenerSpielplanTurnier, setOffenerSpielplanTurnier] = useState(null);

  const nachLoginProfilLaden = async (neueSession) => {
    setProfilLaedt(true);
    try {
      const zeilen = await supabaseSelect("admin_profile", `?user_id=eq.${neueSession.user.id}&select=*`, neueSession.access_token);
      if (zeilen.length > 0) {
        setAdminProfil(zeilen[0]);
        const alle = await supabaseSelect("admin_profile", "?select=*&order=erstellt_am.asc", neueSession.access_token);
        setAdmins(alle);
      }
    } finally {
      setProfilLaedt(false);
    }
  };

  if (!session) {
    return (
      <AdminLogin
        onErfolg={async (neueSession) => {
          setSession(neueSession);
          await nachLoginProfilLaden(neueSession);
        }}
      />
    );
  }

  if (profilLaedt) {
    return <div className="kc-section">Lädt …</div>;
  }

  if (!adminProfil) {
    return (
      <ProfilAnlegen
        onFertig={async (name) => {
          const zeile = await supabaseInsert(
            "admin_profile",
            { user_id: session.user.id, name, email: session.user.email },
            session.access_token
          );
          setAdminProfil(zeile[0]);
          const alle = await supabaseSelect("admin_profile", "?select=*&order=erstellt_am.asc", session.access_token);
          setAdmins(alle);
        }}
      />
    );
  }

  const abmelden = async () => {
    await supabaseAbmelden(session.access_token);
    setSession(null);
    setAdminProfil(null);
    setAdmins([]);
  };

  const neuesTurnierAnlegen = async (daten) => {
    const roh = { id: neueId("turnier"), ...daten, erstelltAm: Date.now() };
    const zeile = await supabaseInsert("turniere", turnierZuDb(roh), session.access_token);
    setTurniere((prev) => [...prev, turnierAusDb(zeile[0])]);
    setZeigeFormular(false);
  };

  const turnierAktualisieren = async (daten) => {
    const id = bearbeitetesTurnier.id;
    const zeile = await supabaseUpdate("turniere", id, turnierZuDb({ id, ...daten }), session.access_token);
    setTurniere((prev) => prev.map((t) => (t.id === id ? turnierAusDb(zeile[0]) : t)));
    setBearbeitetesTurnier(null);
    setZeigeFormular(false);
  };

  const turnierLoeschen = async (id) => {
    if (!confirm("Dieses Turnier wirklich löschen? Alle zugehörigen Anmeldungen und Spielpläne werden mitgelöscht.")) return;
    await supabaseDelete("turniere", id, session.access_token);
    setTurniere((prev) => prev.filter((t) => t.id !== id));
    setAnmeldungen((prev) => prev.filter((a) => a.turnierId !== id)); // DB löscht per on-delete-cascade mit
    setSpielplaene((prev) => prev.filter((p) => p.turnierId !== id));
    if (offenesTurnier === id) setOffenesTurnier(null);
  };

  const anmeldungAktualisieren = async (anmeldungId, neuerStatus) => {
    const anmeldung = anmeldungen.find((a) => a.id === anmeldungId);
    const daten = { status: neuerStatus, bearbeitet_von: adminProfil.name || "" };
    if (neuerStatus === "bestaetigt") daten.bestaetigt_am = new Date().toISOString();
    const zeile = await supabaseUpdate("anmeldungen", anmeldungId, daten, session.access_token);
    const aktualisierteAnmeldung = anmeldungAusDb(zeile[0]);
    setAnmeldungen((prev) => prev.map((a) => (a.id === anmeldungId ? aktualisierteAnmeldung : a)));
    if (anmeldung) {
      const turnier = turniere.find((t) => t.id === anmeldung.turnierId);
      const typ = neuerStatus === "bestaetigt" ? "bestaetigung" : neuerStatus === "abgelehnt" ? "ablehnung" : null;
      if (typ) {
        benachrichtigeBackend(typ, aktualisierteAnmeldung, turnier);
        mailOeffnen(typ, aktualisierteAnmeldung, turnier);
      }
    }
  };

  const ausWartelisteAufnehmen = async (anmeldungId) => {
    const anmeldung = anmeldungen.find((a) => a.id === anmeldungId);
    const neueFrist = Date.now() + DREI_TAGE_MS;
    const zeile = await supabaseUpdate(
      "anmeldungen", anmeldungId,
      { status: "ausstehend", frist: new Date(neueFrist).toISOString(), bearbeitet_von: adminProfil.name || "" },
      session.access_token
    );
    const aktualisierteAnmeldung = anmeldungAusDb(zeile[0]);
    setAnmeldungen((prev) => prev.map((a) => (a.id === anmeldungId ? aktualisierteAnmeldung : a)));
    if (anmeldung) {
      const turnier = turniere.find((t) => t.id === anmeldung.turnierId);
      benachrichtigeBackend("warteliste_aufnahme", aktualisierteAnmeldung, turnier);
      mailOeffnen("warteliste_aufnahme", aktualisierteAnmeldung, turnier);
    }
  };

  const erinnerungSenden = (anmeldung) => {
    const turnier = turniere.find((t) => t.id === anmeldung.turnierId);
    benachrichtigeBackend("erinnerung", anmeldung, turnier);
    mailOeffnen("erinnerung", anmeldung, turnier);
  };

  const alleExportieren = () => {
    csvHerunterladen(`kidzcup-anmeldungen-alle-${Date.now()}.csv`, anmeldungenAlsCsv(anmeldungen, turniere, jetzt));
  };

  const turnierExportieren = (t, regs) => {
    const dateiname = `kidzcup-${t.name.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}-anmeldungen.csv`;
    csvHerunterladen(dateiname, anmeldungenAlsCsv(regs, turniere, jetzt));
  };

  // Art. 17 DSGVO: manuelles Löschen einer einzelnen Anmeldung, z. B. auf Anfrage per E-Mail/Telefon.
  const anmeldungManuellLoeschen = async (anmeldung) => {
    if (!confirm(`Anmeldung von "${anmeldung.verein}" (${anmeldung.jugend}) wirklich endgültig löschen?`)) return;
    await supabaseDelete("anmeldungen", anmeldung.id, session.access_token);
    setAnmeldungen((prev) => prev.filter((a) => a.id !== anmeldung.id));
  };

  // Löschkonzept: personenbezogene Anmeldedaten zu Turnieren, die lange zurückliegen, bereinigen.
  const altdatenLoeschen = async (turnier) => {
    const betroffen = anmeldungen.filter((a) => a.turnierId === turnier.id).length;
    if (!confirm(`Alle ${betroffen} Anmeldung(en) zu "${turnier.name}" (${formatDatum(turnier.datum)}) endgültig löschen? Das Turnier selbst (ohne personenbezogene Daten) bleibt erhalten.`)) return;
    await supabaseDeleteWhere("anmeldungen", `?turnier_id=eq.${turnier.id}`, session.access_token);
    await supabaseDeleteWhere("spielplaene", `?turnier_id=eq.${turnier.id}`, session.access_token);
    setAnmeldungen((prev) => prev.filter((a) => a.turnierId !== turnier.id));
    setSpielplaene((prev) => prev.filter((p) => p.turnierId !== turnier.id));
  };

  const spielplanErstellen = async (turnier, modus, anzahlGruppen) => {
    const bestaetigteIds = anmeldungen
      .filter((a) => a.turnierId === turnier.id && a.status === "bestaetigt")
      .map((a) => a.id);
    const neuerPlan = modus === "gruppen" ? erstelleGruppenplan(bestaetigteIds, anzahlGruppen) : erstelleKoPlan(bestaetigteIds);
    await supabaseDeleteWhere("spielplaene", `?turnier_id=eq.${turnier.id}`, session.access_token);
    const roh = { id: neueId("plan"), turnierId: turnier.id, erstelltAm: Date.now(), ...neuerPlan };
    const zeile = await supabaseInsert("spielplaene", spielplanZuDb(roh), session.access_token);
    setSpielplaene((prev) => [...prev.filter((p) => p.turnierId !== turnier.id), spielplanAusDb(zeile[0])]);
  };

  const spielplanNeuErstellen = async (turnier) => {
    if (!confirm("Bestehenden Spielplan wirklich verwerfen? Alle eingetragenen Ergebnisse gehen dabei verloren.")) return;
    await supabaseDeleteWhere("spielplaene", `?turnier_id=eq.${turnier.id}`, session.access_token);
    setSpielplaene((prev) => prev.filter((p) => p.turnierId !== turnier.id));
  };

  const spielSpeichern = async (turnierId, spielId, heimTore, gastTore, siegerBeiUnentschieden) => {
    const plan = spielplaene.find((p) => p.turnierId === turnierId);
    if (!plan) return;
    const aktualisiert = spielplanMitErgebnis(plan, spielId, heimTore, gastTore, siegerBeiUnentschieden);
    const zeile = await supabaseUpdate("spielplaene", plan.id, spielplanZuDb(aktualisiert), session.access_token);
    setSpielplaene((prev) => prev.map((p) => (p.id === plan.id ? spielplanAusDb(zeile[0]) : p)));
  };

  const dokumentHochladen = async (datei, titel, turnierId) => {
    const id = neueId("dok");
    const dateiendung = datei.name.includes(".") ? datei.name.slice(datei.name.lastIndexOf(".")) : "";
    const pfad = `${turnierId || "allgemein"}/${id}${dateiendung}`;
    await supabaseDateiHochladen(pfad, datei, session.access_token);
    const roh = {
      id, turnierId: turnierId || null, titel: titel || datei.name, dateiname: datei.name,
      pfad, typ: datei.type, groesse: datei.size, hochgeladenVon: adminProfil.name,
    };
    const zeile = await supabaseInsert("dokumente", dokumentZuDb(roh), session.access_token);
    setDokumente((prev) => [dokumentAusDb(zeile[0]), ...prev]);
  };

  const dokumentLoeschen = async (dokument) => {
    if (!confirm(`"${dokument.titel}" wirklich löschen?`)) return;
    let dateiStatus = "ok";
    try {
      await supabaseDateiLoeschen(dokument.pfad, session.access_token);
    } catch (e) {
      dateiStatus = "Datei-Fehler: " + e.message;
    }
    try {
      await supabaseDelete("dokumente", dokument.id, session.access_token);
      setDokumente((prev) => prev.filter((d) => d.id !== dokument.id));
      alert("Gelöscht. (Datei-Speicher: " + dateiStatus + ")");
    } catch (e) {
      alert("Datenbank-Eintrag konnte nicht gelöscht werden: " + e.message + " (Datei-Speicher: " + dateiStatus + ")");
    }
  };

  if (offenerSpielplanTurnier) {
    const plan = spielplaene.find((p) => p.turnierId === offenerSpielplanTurnier.id) || null;
    return (
      <div>
        <button className="kc-zurueck" onClick={() => setOffenerSpielplanTurnier(null)}>← Zurück zur Turnierverwaltung</button>
        <SpielplanVerwaltung
          turnier={offenerSpielplanTurnier}
          anmeldungen={anmeldungen}
          plan={plan}
          onErstellen={(modus, anzahlGruppen) => spielplanErstellen(offenerSpielplanTurnier, modus, anzahlGruppen)}
          onSpielSpeichern={(spielId, h, g, sieger) => spielSpeichern(offenerSpielplanTurnier.id, spielId, h, g, sieger)}
          onNeuErstellen={() => spielplanNeuErstellen(offenerSpielplanTurnier)}
        />
      </div>
    );
  }

  return (
    <div>
      <section className="kc-section">
        <div className="kc-admin-kopf">
          <div>
            <h1 className="kc-h1">Turnierverwaltung</h1>
            <p className="kc-sub">Angemeldet als <strong>{adminProfil.name}</strong> ({adminProfil.email})</p>
          </div>
          <div className="kc-admin-kopf-aktionen">
            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => setZeigePasswortAendern((v) => !v)}>
              Mein Passwort ändern
            </button>
            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => setZeigeAdminsVerwalten((v) => !v)}>
              Admins verwalten
            </button>
            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => setZeigeDatenschutzTools((v) => !v)}>
              Datenschutz &amp; Löschung
            </button>
            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => setZeigeDokumenteVerwalten((v) => !v)}>
              Dokumente
            </button>
            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={alleExportieren} disabled={anmeldungen.length === 0}>
              Alle als CSV exportieren
            </button>
            <button
              className="kc-btn kc-btn--primary"
              onClick={() => {
                setBearbeitetesTurnier(null);
                setZeigeFormular((v) => !v);
              }}
            >
              {zeigeFormular ? "Abbrechen" : "+ Neues Turnier"}
            </button>
            <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={abmelden}>
              Abmelden
            </button>
          </div>
        </div>
      </section>

      {zeigePasswortAendern && (
        <PasswortAendernFormular
          session={session}
          onGeaendert={() => setZeigePasswortAendern(false)}
          onAbbrechen={() => setZeigePasswortAendern(false)}
        />
      )}

      {zeigeAdminsVerwalten && (
        <AdminsVerwalten
          admins={admins}
          eigeneId={adminProfil.user_id}
          onEntfernen={async (userId) => {
            await supabaseDeleteWhere("admin_profile", `?user_id=eq.${userId}`, session.access_token);
            setAdmins((prev) => prev.filter((a) => a.user_id !== userId));
          }}
          onSchliessen={() => setZeigeAdminsVerwalten(false)}
        />
      )}

      {zeigeDatenschutzTools && (
        <DatenschutzLoeschTools
          turniere={turniere}
          anmeldungen={anmeldungen}
          onAltdatenLoeschen={altdatenLoeschen}
          onSchliessen={() => setZeigeDatenschutzTools(false)}
        />
      )}

      {zeigeDokumenteVerwalten && (
        <DokumenteVerwalten
          turniere={turniere}
          dokumente={dokumente}
          onHochladen={dokumentHochladen}
          onLoeschen={dokumentLoeschen}
          onSchliessen={() => setZeigeDokumenteVerwalten(false)}
        />
      )}

      {zeigeFormular && (
        <TurnierFormular
          bestehendesTurnier={bearbeitetesTurnier}
          onAbsenden={bearbeitetesTurnier ? turnierAktualisieren : neuesTurnierAnlegen}
          onAbbrechen={() => { setZeigeFormular(false); setBearbeitetesTurnier(null); }}
        />
      )}

      <div className="kc-liste">
        {turniere.length === 0 && <div className="kc-empty">Noch keine Turniere angelegt.</div>}
        {[...turniere].sort((a, b) => new Date(a.datum) - new Date(b.datum)).map((t) => {
          const regsFuerTurnier = anmeldungen.filter((a) => a.turnierId === t.id);
          const wartelisteRegs = regsFuerTurnier.filter((a) => effektiverStatus(a, jetzt) === "warteliste");
          const aktiveRegs = regsFuerTurnier.filter((a) => effektiverStatus(a, jetzt) !== "warteliste");
          const belegt = belegtePlaetze(t.id);
          const frei = Math.max(0, t.maxPlaetze - belegt);
          const offen = offenesTurnier === t.id;
          return (
            <div className="kc-karte" key={t.id} style={{ borderLeftColor: "var(--kc-blue)" }}>
              <div className="kc-karte__kopf">
                <h2 className="kc-karte__titel">{t.name}</h2>
                <div className="kc-karte__zahl">
                  <span className="kc-zahl-gross">{belegt}/{t.maxPlaetze}</span>
                  <span className="kc-zahl-label">belegt{wartelisteRegs.length > 0 ? ` · ${wartelisteRegs.length} Warteliste` : ""}</span>
                </div>
              </div>
              <dl className="kc-details">
                <div><dt>Termin</dt><dd>{formatDatum(t.datum)}</dd></div>
                <div><dt>Ort</dt><dd>{t.ort}</dd></div>
                <div><dt>Gebühr</dt><dd>{t.preis} €</dd></div>
                <div><dt>Zahlungslink</dt><dd className="kc-link-truncate">{t.zahlLink || "– nicht hinterlegt –"}</dd></div>
              </dl>
              <div className="kc-admin-aktionen">
                <button className="kc-btn kc-btn--sekundaer" onClick={() => setOffenesTurnier(offen ? null : t.id)}>
                  {offen ? "Anmeldungen ausblenden" : `Anmeldungen anzeigen (${regsFuerTurnier.length})`}
                </button>
                <button
                  className="kc-btn kc-btn--sekundaer"
                  onClick={() => { setBearbeitetesTurnier(t); setZeigeFormular(true); }}
                >
                  Bearbeiten
                </button>
                <button className="kc-btn kc-btn--sekundaer" onClick={() => setOffenerSpielplanTurnier(t)}>
                  {spielplaene.some((p) => p.turnierId === t.id) ? "Spielplan verwalten" : "Spielplan erstellen"}
                </button>
                <button
                  className="kc-btn kc-btn--sekundaer"
                  onClick={() => turnierExportieren(t, regsFuerTurnier)}
                  disabled={regsFuerTurnier.length === 0}
                >
                  CSV exportieren
                </button>
                <button className="kc-btn kc-btn--gefahr" onClick={() => turnierLoeschen(t.id)}>Löschen</button>
              </div>

              {offen && (
                <div className="kc-anmeldungs-tabelle">
                  {regsFuerTurnier.length === 0 && <p className="kc-notiz">Noch keine Anmeldungen.</p>}
                  {aktiveRegs.map((a) => {
                    const st = effektiverStatus(a, jetzt);
                    return (
                      <div className="kc-anmeldungs-zeile" key={a.id}>
                        <div>
                          <strong>{a.verein}</strong> – Jahrgang {a.jahrgang} ({a.jugend}) · Trainer: {a.trainer}
                          <div className="kc-notiz">{a.email} · {a.telefon}</div>
                          {a.notfallkontakt && <div className="kc-notiz">Notfallkontakt: {a.notfallkontakt}</div>}
                          <div className="kc-notiz">Frist: {formatDatumZeit(a.frist)}</div>
                          {a.zahlungsreferenz && <div className="kc-notiz">Referenz: {a.zahlungsreferenz}</div>}
                          {a.bearbeitetVon && <div className="kc-notiz">Bearbeitet von: {a.bearbeitetVon}</div>}
                        </div>
                        <span className="kc-status-badge kc-status-badge--klein" style={{ background: STATUS_FARBE[st] }}>
                          {STATUS_LABEL[st]}
                        </span>
                        {st === "zahlung_gemeldet" && (
                          <div className="kc-admin-aktionen kc-admin-aktionen--klein">
                            <button className="kc-btn kc-btn--primary kc-btn--klein" onClick={() => anmeldungAktualisieren(a.id, "bestaetigt")}>Bestätigen</button>
                            <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={() => anmeldungAktualisieren(a.id, "abgelehnt")}>Ablehnen</button>
                          </div>
                        )}
                        {st === "ausstehend" && (
                          <div className="kc-admin-aktionen kc-admin-aktionen--klein">
                            <button className="kc-btn kc-btn--sekundaer kc-btn--klein" onClick={() => erinnerungSenden(a)}>
                              ✉️ Erinnerung senden
                            </button>
                          </div>
                        )}
                        <div className="kc-admin-aktionen kc-admin-aktionen--klein">
                          <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={() => anmeldungManuellLoeschen(a)} title="Löschung auf Anfrage, z. B. bei Auskunftsersuchen">
                            🗑 Daten löschen
                          </button>
                        </div>
                      </div>
                    );
                  })}

                  {wartelisteRegs.length > 0 && (
                    <div className="kc-warteliste-block">
                      <h3 className="kc-h3">Warteliste ({wartelisteRegs.length})</h3>
                      {wartelisteRegs.map((a) => (
                        <div className="kc-anmeldungs-zeile" key={a.id}>
                          <div>
                            <strong>{a.verein}</strong> – Jahrgang {a.jahrgang} ({a.jugend}) · Trainer: {a.trainer}
                            <div className="kc-notiz">{a.email} · {a.telefon}</div>
                            <div className="kc-notiz">Angemeldet: {formatDatumZeit(a.angemeldetAm)}</div>
                          </div>
                          <span className="kc-status-badge kc-status-badge--klein" style={{ background: STATUS_FARBE.warteliste }}>
                            {STATUS_LABEL.warteliste}
                          </span>
                          <div className="kc-admin-aktionen kc-admin-aktionen--klein">
                            <button
                              className="kc-btn kc-btn--primary kc-btn--klein"
                              disabled={frei === 0}
                              onClick={() => ausWartelisteAufnehmen(a.id)}
                            >
                              {frei === 0 ? "Kein Platz frei" : "In Turnier aufnehmen"}
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ProfilAnlegen({ onFertig }) {
  const [name, setName] = useState("");
  const [speichertGerade, setSpeichertGerade] = useState(false);
  const [fehler, setFehler] = useState("");

  const absenden = async (e) => {
    e.preventDefault();
    if (!name.trim()) { setFehler("Bitte einen Namen angeben."); return; }
    setFehler("");
    setSpeichertGerade(true);
    try {
      await onFertig(name.trim());
    } catch (err) {
      setFehler("Profil konnte nicht angelegt werden: " + err.message);
      setSpeichertGerade(false);
    }
  };

  return (
    <div className="kc-section kc-login">
      <h1 className="kc-h1">Willkommen!</h1>
      <p className="kc-sub">Du bist erfolgreich eingeloggt. Bevor es losgeht, brauchen wir noch deinen Anzeigenamen für die Turnierverwaltung.</p>
      <form className="kc-formular" onSubmit={absenden}>
        <label className="kc-feld">
          <span>Dein Name</span>
          <input className="kc-input" value={name} onChange={(e) => setName(e.target.value)} required autoFocus />
        </label>
        {fehler && <p className="kc-fehler">{fehler}</p>}
        <button className="kc-btn kc-btn--primary" type="submit" disabled={speichertGerade}>Weiter</button>
      </form>
    </div>
  );
}

function AdminLogin({ onErfolg }) {
  const [email, setEmail] = useState("");
  const [pwEingabe, setPwEingabe] = useState("");
  const [pwFehler, setPwFehler] = useState("");
  const [fehlversuche, setFehlversuche] = useState(0);
  const [gesperrtBis, setGesperrtBis] = useState(0);
  const [jetzt, setJetzt] = useState(Date.now());
  const [pruefeGerade, setPruefeGerade] = useState(false);

  useEffect(() => {
    if (gesperrtBis <= Date.now()) return;
    const iv = setInterval(() => setJetzt(Date.now()), 1000);
    return () => clearInterval(iv);
  }, [gesperrtBis]);

  const gesperrt = gesperrtBis > jetzt;
  const restSekunden = Math.ceil((gesperrtBis - jetzt) / 1000);

  const versuchen = async () => {
    if (gesperrt || pruefeGerade) return;
    setPruefeGerade(true);
    try {
      const session = await supabaseAnmelden(email.trim().toLowerCase(), pwEingabe);
      setPwFehler("");
      onErfolg(session);
    } catch (err) {
      const neueFehlversuche = fehlversuche + 1;
      setFehlversuche(neueFehlversuche);
      if (neueFehlversuche >= MAX_FEHLVERSUCHE) {
        setGesperrtBis(Date.now() + SPERR_DAUER_MS);
        setPwFehler(`Zu viele Fehlversuche. Bitte ${Math.ceil(SPERR_DAUER_MS / 1000)} Sekunden warten.`);
      } else {
        setPwFehler(`Anmeldung fehlgeschlagen: ${err.message} (${neueFehlversuche}/${MAX_FEHLVERSUCHE} Versuche)`);
      }
      setPwEingabe("");
    } finally {
      setPruefeGerade(false);
    }
  };

  return (
    <div className="kc-section kc-login">
      <h1 className="kc-h1">Admin-Bereich</h1>
      <p className="kc-sub">Bitte mit E-Mail und Passwort anmelden, um Turniere zu verwalten.</p>
      <div className="kc-formular">
        <label className="kc-feld">
          <span>E-Mail</span>
          <input
            className="kc-input"
            type="email"
            value={email}
            disabled={gesperrt || pruefeGerade}
            onChange={(e) => setEmail(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && versuchen()}
            autoCapitalize="none"
            autoCorrect="off"
            autoComplete="email"
            spellCheck={false}
          />
        </label>
        <label className="kc-feld">
          <span>Passwort</span>
          <input
            className="kc-input"
            type="password"
            value={pwEingabe}
            disabled={gesperrt || pruefeGerade}
            onChange={(e) => setPwEingabe(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && versuchen()}
            autoCapitalize="none"
            autoCorrect="off"
            autoComplete="current-password"
            spellCheck={false}
          />
        </label>
        <button className="kc-btn kc-btn--primary" onClick={versuchen} disabled={gesperrt || pruefeGerade || !pwEingabe || !email}>
          {gesperrt ? `Gesperrt (${restSekunden}s)` : "Anmelden"}
        </button>
      </div>
      {pwFehler && <p className="kc-fehler">{pwFehler}</p>}
      <p className="kc-notiz">
        Noch keinen Zugang? Der erste Admin-Zugang wird im Supabase-Dashboard unter „Authentication → Users" angelegt,
        nicht hier in der App.
      </p>
    </div>
  );
}

function PasswortAendernFormular({ session, onGeaendert, onAbbrechen }) {
  const [neu1, setNeu1] = useState("");
  const [neu2, setNeu2] = useState("");
  const [fehler, setFehler] = useState("");
  const [speichertGerade, setSpeichertGerade] = useState(false);

  const absenden = async (e) => {
    e.preventDefault();
    setFehler("");
    if (neu1.length < 8) { setFehler("Das neue Passwort muss mindestens 8 Zeichen haben."); return; }
    if (neu1 !== neu2) { setFehler("Die neuen Passwörter stimmen nicht überein."); return; }
    setSpeichertGerade(true);
    try {
      await supabasePasswortAendern(session.access_token, neu1);
      onGeaendert();
    } catch (err) {
      setFehler("Fehler: " + err.message);
      setSpeichertGerade(false);
    }
  };

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">Mein Passwort ändern</h2>
      <form className="kc-formular" onSubmit={absenden}>
        <label className="kc-feld">
          <span>Neues Passwort (mind. 8 Zeichen)</span>
          <input className="kc-input" type="password" value={neu1} onChange={(e) => setNeu1(e.target.value)} required />
        </label>
        <label className="kc-feld">
          <span>Neues Passwort bestätigen</span>
          <input className="kc-input" type="password" value={neu2} onChange={(e) => setNeu2(e.target.value)} required />
        </label>
        {fehler && <p className="kc-fehler">{fehler}</p>}
        <div className="kc-admin-aktionen">
          <button className="kc-btn kc-btn--primary" type="submit" disabled={speichertGerade}>Passwort speichern</button>
          <button className="kc-btn kc-btn--sekundaer" type="button" onClick={onAbbrechen}>Abbrechen</button>
        </div>
      </form>
    </div>
  );
}

function AdminsVerwalten({ admins, eigeneId, onEntfernen, onSchliessen }) {
  const entfernen = (admin) => {
    if (admins.length <= 1) { alert("Der letzte verbleibende Admin-Zugang kann hier nicht entfernt werden."); return; }
    if (!confirm(`"${admin.name}" (${admin.email}) hier aus der Turnierverwaltung entfernen? Das Supabase-Login bleibt bestehen, verliert aber sofort alle Admin-Rechte in dieser App.`)) return;
    onEntfernen(admin.user_id);
  };

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">Admin-Zugänge</h2>
      <div className="kc-anmeldungs-tabelle">
        {admins.map((a) => (
          <div className="kc-anmeldungs-zeile" key={a.user_id}>
            <div>
              <strong>{a.name}</strong> {a.user_id === eigeneId && <span className="kc-notiz">(du)</span>}
              <div className="kc-notiz">{a.email} · seit {formatDatum(new Date(a.erstellt_am).toISOString().slice(0, 10))}</div>
            </div>
            <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={() => entfernen(a)} disabled={admins.length <= 1}>
              Entfernen
            </button>
          </div>
        ))}
      </div>

      <div className="kc-hinweis" style={{ marginTop: "14px" }}>
        Einen neuen Admin hinzufügen: im Supabase-Dashboard unter „Authentication → Users" auf „Add user" bzw.
        „Invite user" klicken. Sobald sich die Person zum ersten Mal hier in der App einloggt, wird sie nach ihrem
        Namen gefragt und taucht danach automatisch in dieser Liste auf.
      </div>

      <div className="kc-admin-aktionen" style={{ marginTop: "14px" }}>
        <button className="kc-btn kc-btn--sekundaer" onClick={onSchliessen}>Schließen</button>
      </div>
    </div>
  );
}

function DatenschutzLoeschTools({ turniere, anmeldungen, onAltdatenLoeschen, onSchliessen }) {
  const alteTurniere = turniere
    .filter((t) => monateSeitDatum(t.datum) >= AUFBEWAHRUNG_MONATE)
    .filter((t) => anmeldungen.some((a) => a.turnierId === t.id))
    .sort((a, b) => new Date(a.datum) - new Date(b.datum));

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">Datenschutz &amp; Löschung</h2>
      <p className="kc-sub">
        Empfohlene Aufbewahrungsdauer für personenbezogene Anmeldedaten: {AUFBEWAHRUNG_MONATE} Monate nach
        Turnierdatum. Danach markiert die App betroffene Turniere hier automatisch zur Bereinigung –
        gelöscht wird aber nur, wenn ihr das aktiv bestätigt. Prüft vorher, ob bei euch andere
        vereins- oder handelsrechtliche Aufbewahrungspflichten gelten.
      </p>

      {alteTurniere.length === 0 ? (
        <p className="kc-notiz">Aktuell gibt es keine Turniere, deren Anmeldedaten die {AUFBEWAHRUNG_MONATE}-Monats-Frist überschritten haben.</p>
      ) : (
        <div className="kc-anmeldungs-tabelle">
          {alteTurniere.map((t) => {
            const anzahl = anmeldungen.filter((a) => a.turnierId === t.id).length;
            return (
              <div className="kc-anmeldungs-zeile" key={t.id}>
                <div>
                  <strong>{t.name}</strong>
                  <div className="kc-notiz">{formatDatum(t.datum)} · {anzahl} Anmeldung(en) · {monateSeitDatum(t.datum)} Monate her</div>
                </div>
                <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={() => onAltdatenLoeschen(t)}>
                  Anmeldedaten jetzt löschen
                </button>
              </div>
            );
          })}
        </div>
      )}

      <div className="kc-admin-aktionen" style={{ marginTop: "14px" }}>
        <button className="kc-btn kc-btn--sekundaer" onClick={onSchliessen}>Schließen</button>
      </div>

      <p className="kc-notiz" style={{ marginTop: "10px" }}>
        Einzelne Anmeldungen könnt ihr jederzeit auch unabhängig vom Alter über „🗑 Daten löschen" in der
        jeweiligen Turnier-Anmeldungsliste entfernen, z. B. wenn ein Verein die Löschung seiner Daten anfragt.
      </p>
    </div>
  );
}

function DokumenteVerwalten({ turniere, dokumente, onHochladen, onLoeschen, onSchliessen }) {
  const [titel, setTitel] = useState("");
  const [turnierId, setTurnierId] = useState(""); // "" = allgemein
  const [datei, setDatei] = useState(null);
  const [laedtHoch, setLaedtHoch] = useState(false);
  const [fehler, setFehler] = useState("");

  const hochladen = async (e) => {
    e.preventDefault();
    if (!datei) { setFehler("Bitte eine Datei auswählen."); return; }
    setFehler("");
    setLaedtHoch(true);
    try {
      await onHochladen(datei, titel.trim() || datei.name, turnierId || null);
      setTitel(""); setDatei(null); setTurnierId("");
      const eingabe = document.getElementById("kc-datei-input");
      if (eingabe) eingabe.value = "";
    } catch (err) {
      setFehler("Upload fehlgeschlagen: " + err.message);
    } finally {
      setLaedtHoch(false);
    }
  };

  const turnierName = (id) => (id ? (turniere.find((t) => t.id === id)?.name || "unbekanntes Turnier") : "Allgemein");

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">Dokumente</h2>
      <p className="kc-sub">PDFs oder Bilder hochladen, die Vereine ohne Login herunterladen können (z. B. Hallenplan, Teilnahmebedingungen, Anfahrtsskizze). Max. 20 MB pro Datei.</p>

      <form className="kc-formular" onSubmit={hochladen}>
        <label className="kc-feld">
          <span>Titel</span>
          <input className="kc-input" value={titel} onChange={(e) => setTitel(e.target.value)} placeholder="z. B. Hallenplan" />
        </label>
        <label className="kc-feld">
          <span>Gilt für</span>
          <select className="kc-input" value={turnierId} onChange={(e) => setTurnierId(e.target.value)}>
            <option value="">Allgemein (alle Turniere)</option>
            {turniere.map((t) => (
              <option key={t.id} value={t.id}>{t.name}</option>
            ))}
          </select>
        </label>
        <label className="kc-feld">
          <span>Datei (PDF oder Bild)</span>
          <input id="kc-datei-input" className="kc-input" type="file" accept=".pdf,image/*" onChange={(e) => setDatei(e.target.files[0] || null)} />
        </label>
        {fehler && <p className="kc-fehler">{fehler}</p>}
        <button className="kc-btn kc-btn--primary" type="submit" disabled={laedtHoch}>
          {laedtHoch ? "Lädt hoch …" : "Hochladen"}
        </button>
      </form>

      <div className="kc-anmeldungs-tabelle" style={{ marginTop: "16px" }}>
        {dokumente.length === 0 && <p className="kc-notiz">Noch keine Dokumente hochgeladen.</p>}
        {dokumente.map((d) => (
          <div className="kc-anmeldungs-zeile" key={d.id}>
            <div>
              <strong>{d.titel}</strong>
              <div className="kc-notiz">{turnierName(d.turnierId)} · {d.dateiname}{d.groesse ? ` · ${(d.groesse / 1024).toFixed(0)} KB` : ""}</div>
            </div>
            <div className="kc-admin-aktionen kc-admin-aktionen--klein">
              <a className="kc-btn kc-btn--sekundaer kc-btn--klein" href={dateiOeffentlicheUrl(d.pfad)} target="_blank" rel="noopener noreferrer">Ansehen</a>
              <button className="kc-btn kc-btn--gefahr kc-btn--klein" onClick={() => onLoeschen(d)}>Löschen</button>
            </div>
          </div>
        ))}
      </div>

      <div className="kc-admin-aktionen" style={{ marginTop: "14px" }}>
        <button className="kc-btn kc-btn--sekundaer" onClick={onSchliessen}>Schließen</button>
      </div>
    </div>
  );
}

function TurnierFormular({ bestehendesTurnier, onAbsenden, onAbbrechen }) {
  const [form, setForm] = useState(() =>
    bestehendesTurnier
      ? {
          name: bestehendesTurnier.name,
          datum: bestehendesTurnier.datum,
          ort: bestehendesTurnier.ort,
          maxPlaetze: String(bestehendesTurnier.maxPlaetze),
          preis: String(bestehendesTurnier.preis),
          zahlLink: bestehendesTurnier.zahlLink || "",
        }
      : { name: "", datum: "", ort: "", maxPlaetze: "16", preis: "25", zahlLink: "" }
  );
  const feld = (name) => (e) => setForm({ ...form, [name]: e.target.value });
  const gueltig = form.name.trim() && form.datum && form.ort.trim() && Number(form.maxPlaetze) > 0 && Number(form.preis) >= 0;

  return (
    <div className="kc-section kc-formular-karte">
      <h2 className="kc-h2">{bestehendesTurnier ? `Turnier bearbeiten: ${bestehendesTurnier.name}` : "Neues Turnier anlegen"}</h2>
      <form
        className="kc-formular"
        onSubmit={(e) => {
          e.preventDefault();
          if (!gueltig) return;
          onAbsenden({ ...form, maxPlaetze: Number(form.maxPlaetze), preis: Number(form.preis) });
        }}
      >
        <label className="kc-feld">
          <span>Turniername</span>
          <input className="kc-input" value={form.name} onChange={feld("name")} placeholder="z. B. KIDZCUP Frühjahrscup U10" required />
        </label>
        <div className="kc-feld-reihe">
          <label className="kc-feld">
            <span>Datum</span>
            <input className="kc-input" type="date" value={form.datum} onChange={feld("datum")} required />
          </label>
          <label className="kc-feld">
            <span>Ort</span>
            <input className="kc-input" value={form.ort} onChange={feld("ort")} required />
          </label>
        </div>
        <div className="kc-feld-reihe">
          <label className="kc-feld">
            <span>Max. Plätze</span>
            <input className="kc-input" type="number" min="1" value={form.maxPlaetze} onChange={feld("maxPlaetze")} required />
          </label>
          <label className="kc-feld">
            <span>Startgebühr (€)</span>
            <input className="kc-input" type="number" min="0" step="0.5" value={form.preis} onChange={feld("preis")} required />
          </label>
        </div>
        <label className="kc-feld">
          <span>Zahlungslink (z. B. PayPal.me oder Stripe Payment Link)</span>
          <input className="kc-input" type="url" value={form.zahlLink} onChange={feld("zahlLink")} placeholder="https://" />
        </label>
        <div className="kc-admin-aktionen">
          <button className="kc-btn kc-btn--primary" type="submit" disabled={!gueltig}>
            {bestehendesTurnier ? "Änderungen speichern" : "Turnier speichern"}
          </button>
          {onAbbrechen && (
            <button className="kc-btn kc-btn--sekundaer" type="button" onClick={onAbbrechen}>Abbrechen</button>
          )}
        </div>
      </form>
    </div>
  );
}

